#!/usr/bin/env bash
# Non-interactive end-to-end checks against two fake machines (needs bash + jq).
#   cargo build && tests/e2e-fake/smoke.sh          (or: smoke.sh release)
set -u
ROOT=$(cd "$(dirname "$0")" && pwd)
# never against the real machine: only from tests/e2e-fake, with its fake world
[ -f "$ROOT/env.sh" ] && [ "$(basename "$ROOT")" = "e2e-fake" ] || { echo "smoke.sh: run it from tests/e2e-fake (no fake world here)" >&2; exit 2; }
source "$ROOT/env.sh" "${1:-debug}" || exit 2
case "${ST:-}:${HOME:-}" in *e2e-fake/.run*:*e2e-fake/.run*) ;; *) echo "smoke.sh: the fake world didn't load (ST/HOME aren't isolated)" >&2; exit 2;; esac
"$ROOT/reset.sh"
pass=0; fail=0
check() { # check <name> <command…>  (passes when the command succeeds)
  local n=$1; shift
  if out=$("$@" 2>&1); then pass=$((pass+1)); printf '  \033[32m✓\033[0m %s\n' "$n"
  else fail=$((fail+1)); printf '  \033[31m✗\033[0m %s\n%s\n' "$n" "$(printf '%s' "$out" | tail -n 8 | sed 's/^/      /')"; fi
}
ch() { aleph "$@" </dev/null; }
has() { grep -q -- "$1"; }

echo "aleph smoke · $(aleph version 2>/dev/null | head -1)"
check "help lists the fleet commands"      sh -c 'aleph help </dev/null | grep -q "aleph wall"'
check "help <cmd> shows details"            sh -c 'aleph help new </dev/null | grep -q -- "--worktree"'
check "ls --json lists both machines"       sh -c 'aleph ls --json </dev/null | jq -e ".hosts | length == 2"'
check "ls --json lists every agent (3 claude + 1 codex)" sh -c 'aleph ls --json </dev/null | jq -e "[.hosts[].sessions[]] | (length == 4) and (map(.agent) | index(\"codex\") != null)"'
check "ls --json carries names/titles/hues" sh -c 'aleph ls --json </dev/null | jq -e "[.hosts[].sessions[] | select(.name==\"ignite\" and .title!=\"\" and .hue==\"amber\")] | length == 1"'
check "ls piped is TSV"                     sh -c 'aleph ls </dev/null | awk -F"\t" "NF>=6" | grep -q "^gpu2	claude_weave"'
check "--host narrows to one machine"       sh -c 'aleph --host gpu2 ls --json </dev/null | jq -e ".hosts | length == 1"'
check "status --json counts"                sh -c 'aleph status --live --json </dev/null | jq -e ".total == 4 and .blocked == 1 and .working == 1 and .done == 1 and .idle == 1"'
check "status --short"                      sh -c 'aleph status --live --short </dev/null | grep -q "▲1"'
check "send reaches a working session"      sh -c 'aleph send ignite "run the tests" </dev/null && grep -q "PROMPT w1:p3 run the tests" "$ST/log"'
check "send to a blocked session explains"  sh -c '! aleph send temper hi </dev/null 2>&1 | grep -q x; aleph send temper hi </dev/null 2>&1 | grep -q "waiting on a question"'
check "keys answers a question"             sh -c 'aleph keys temper 1 </dev/null && grep -q "agent send-keys w1:p2 1" "$ST/log"'
check "host:name picks the machine"         sh -c 'aleph keys gpu2:weave enter </dev/null && grep -Eq "^ssh .* gpu2 .*agent.*send-keys.*w1:p4.*enter" "$ST/log"'
check "herdr calls ride the shared ssh"     sh -c '! grep -q "^herdr --machine" "$ST/log" && grep -q "ControlMaster=auto" "$ST/log"'
check "herdr_via=machine still works"       sh -c 'CC_HERDR_VIA=machine aleph ls --json </dev/null | jq -e ".hosts | length == 2" >/dev/null && grep -q "^herdr --machine b31 api snapshot" "$ST/log"'
check "rename keeps prefix and folder"      sh -c 'aleph rename ignite spark </dev/null && grep -q "tab rename w1:t3 claude_spark:ox_color_check" "$ST/log"'
check "close --yes --worktree: after the grace, pane and worktree" sh -c 'aleph settings set close.grace 1s </dev/null >/dev/null; aleph close weave --yes --worktree </dev/null; r=$?; aleph settings unset close.grace </dev/null >/dev/null; [ $r -eq 0 ] && aleph ls --json </dev/null | jq -e "[.hosts[].sessions[] | select(.name==\"weave\")] | length == 0" >/dev/null && grep -q "WORKTREE-REMOVE w1" "$ST/log"'
check "unknown session is an error"         sh -c '! aleph send nosuch hi </dev/null'
check "a plain shell takes messages and keys (pane run, pane send-keys)" sh -c 'T="$ST/tabs_b31.json"; cp "$T" "$T.sh"; jq ".result.tabs += [{\"tab_id\":\"w1:t55\",\"label\":\"shell_dune\"}]" "$T.sh" > "$T"; echo "[{\"pane_id\":\"w1:p55\",\"tab_id\":\"w1:t55\"}]" > "$ST/panes_b31.json"; : > "$ST/log"; aleph send b31:dune "ls -la" </dev/null >/dev/null 2>&1 && aleph keys b31:dune enter </dev/null >/dev/null 2>&1; r=$?; cp "$T.sh" "$T"; rm -f "$ST/panes_b31.json" "$T.sh"; [ $r -eq 0 ] && grep -q "RUN w1:p55 ls -la" "$ST/log" && grep -q "pane send-keys w1:p55 enter" "$ST/log"'
check "settings set/get"                    sh -c 'aleph settings set refresh 5 </dev/null && [ "$(aleph settings get refresh </dev/null)" = 5 ]'
check "settings rejects bad values"         sh -c '! aleph settings set stats maybe </dev/null'
# --- aleph setup: line mode without a tty, one step, the declarative --apply (into its own file)
check "setup --plain runs without a tty"     sh -c 'aleph setup --plain </dev/null 2>&1 | grep -q "\[1/6\] Machines"'
check "setup <step> --plain runs one step"   sh -c 'aleph setup agents --plain </dev/null 2>&1 | grep -q "\[3/6\] Agents" && ! aleph setup look --plain </dev/null 2>/dev/null && ! aleph setup nosuch </dev/null 2>/dev/null'
check "setup --apply writes what the file says" sh -c 'F="$ST/../../../fixtures/setup-apply.toml"; C="$ST/apply.toml"; rm -f "$C"; ALEPH_CONFIG="$C" aleph setup --apply "$F" --dry-run </dev/null >/dev/null 2>&1 && ! grep -q dark "$C" 2>/dev/null && ALEPH_CONFIG="$C" aleph setup --apply "$F" </dev/null >/dev/null 2>&1 && [ "$(ALEPH_CONFIG="$C" aleph settings get theme </dev/null)" = dark ] && [ "$(ALEPH_CONFIG="$C" aleph settings get ssh_host </dev/null)" = gpu2 ] && ALEPH_CONFIG="$C" aleph preset ls --json </dev/null | jq -e "any(.[]; .name==\"pair\")" >/dev/null && grep -q "aleph completions zsh" "$HOME/.zshrc" && ALEPH_CONFIG="$C" aleph setup --apply "$F" </dev/null 2>&1 | grep -q "no settings change"'
check "setup --apply refuses a bad file"     sh -c 'printf "[ui]\ntheme = \"purple\"\n" > "$ST/bad.toml"; ! ALEPH_CONFIG="$ST/x.toml" aleph setup --apply "$ST/bad.toml" </dev/null 2>/dev/null && ! grep -q purple "$ST/x.toml" 2>/dev/null'
check "preset add/ls --json"                sh -c 'aleph preset add px --host b31 --dir /srv/px --worktree -- --model opus </dev/null && aleph preset ls --json </dev/null | jq -e ".[0].name==\"px\" and .[0].worktree==true"'
check "host list --json marks the fleet"    sh -c 'aleph host list --json </dev/null | jq -e "[.[] | select(.fleet)] | length == 2"'
check "machines got distinct colours"       sh -c 'aleph host list --json </dev/null | jq -e "[.[] | select(.fleet) | .color] | unique | length == 2"'
check "history/recent work when empty"      sh -c 'aleph history --json </dev/null | jq -e "type==\"array\"" && aleph recent --json </dev/null | jq -e "type==\"array\""'
check "agents: per-machine TSV"             sh -c 'aleph agents </dev/null | grep -q "^gpu2	codex	0.40.1	– none	no"'
check "agents --json: integration states"   sh -c 'aleph agents --json </dev/null | jq -e "[.hosts[] | select(.alias==\"gpu2\") | .agents[] | select(.id==\"claude\")][0] | .installed and .integration_state==\"outdated\" and .persistence"'
check "agents --json: this computer too"    sh -c 'aleph settings set local true </dev/null >/dev/null && aleph agents --json </dev/null | jq -e "[.hosts[].alias] == [\"b31\",\"gpu2\",\"local\"] and (.hosts[2].reachable)"; r=$?; aleph settings set local false </dev/null >/dev/null; exit $r'
check "agents setup installs integrations"  sh -c 'aleph --host gpu2 agents setup codex --yes </dev/null && grep -q "herdr integration install codex" "$ST/log" && grep -q "^codex current" "$ST/integ_gpu2"'
check "agents setup refuses without a tty"  sh -c '! aleph agents setup </dev/null'
check "agents finds one outside the PATH"   sh -c 'mkdir -p "$RHOME/.opencode/bin" && printf "#!/bin/sh\necho 1.18.15\n" > "$RHOME/.opencode/bin/opencode" && chmod +x "$RHOME/.opencode/bin/opencode" && aleph --host b31 agents --refresh --json </dev/null | jq -e "[.hosts[0].agents[] | select(.id==\"opencode\")][0] | .installed and .version==\"1.18.15\" and (.path | endswith(\".opencode/bin/opencode\")) and .on_path==false and .glyph!=null"; r=$?; rm -rf "$RHOME/.opencode"; exit $r'
check "agents tells a same-named program apart" sh -c 'mkdir -p "$RHOME/bin" && printf "#!/bin/sh\necho \"pi (cln) 1.3.6\"\n" > "$RHOME/bin/pi" && chmod +x "$RHOME/bin/pi" && aleph --host b31 agents --refresh --json </dev/null | jq -e ".hosts[0] | ([.agents[] | select(.id==\"pi\")][0].installed | not) and ([.skipped[] | select(.id==\"pi\" and .kind==\"other_program\")] | length == 1)"; r=$?; rm -rf "$RHOME/bin"; exit $r'
check "agents --json: OS, tools, install plans" sh -c 'aleph --host b31 agents --json </dev/null | jq -e ".hosts[0] | (.os | length > 0) and ([.tools[].name] | index(\"npm\") != null) and ([.agents[] | select(.id==\"gemini\")][0] | .install_command==\"npm i -g @google/gemini-cli\" and .install_ready and (.prerequisites | length >= 2))"'
check "agents are cached; --refresh looks again" sh -c 'aleph --host gpu2 agents --json </dev/null >/dev/null; n=$(grep -c "^ssh .* gpu2 sh -s" "$ST/log"); aleph --host gpu2 agents --json </dev/null | jq -e ".hosts[0].cached" >/dev/null && [ "$(grep -c "^ssh .* gpu2 sh -s" "$ST/log")" = "$n" ] && aleph --host gpu2 agents --refresh --json </dev/null | jq -e ".hosts[0].cached | not" >/dev/null'
check "agents install --dry-run runs nothing" sh -c 'aleph agents install gemini --host b31 --dry-run </dev/null 2>&1 | grep -q "npm i -g @google/gemini-cli" && ! grep -q "^npm i -g" "$ST/log" && [ ! -e "$RHOME/.npm-global/bin/gemini" ]'
check "agents install asks (no tty, no --yes)" sh -c '! aleph agents install gemini --host b31 </dev/null 2>/dev/null && ! grep -q "^npm i -g" "$ST/log"'
check "agents install: npm, then it's confirmed" sh -c 'o=$(aleph agents install gemini --host b31 --yes </dev/null 2>&1) && grep -q "^npm i -g @google/gemini-cli" "$ST/log" && [ -x "$RHOME/.npm-global/bin/gemini" ] && printf "%s" "$o" | grep -q "Gemini CLI 0.9.0 installed on b31" && printf "%s" "$o" | grep -q "added 1 package" && printf "%s" "$o" | grep -q "PATH" && aleph --host b31 agents --json </dev/null | jq -e "[.hosts[0].agents[] | select(.id==\"gemini\")][0].installed"'
check "agents install: already there"       sh -c 'aleph agents install gemini --host b31 --yes </dev/null 2>&1 | grep -q "already installed on b31"; r=$?; rm -rf "$RHOME/.npm-global"; exit $r'
check "agents install never runs sudo"      sh -c 'touch "$ST/npm_sudo"; o=$(aleph agents install qwen --host b31 --yes </dev/null 2>&1); r=$?; rm -f "$ST/npm_sudo"; [ $r -ne 0 ] && printf "%s" "$o" | grep -q "never runs sudo" && ! grep -q "^sudo" "$ST/log"'
check "agents install --dry-run: the command, nothing run" sh -c ': > "$ST/log"; o=$(aleph agents install grok --host b31 --dry-run </dev/null 2>&1); printf "%s" "$o" | grep -q "x.ai/cli/install.sh" && ! grep -q "x.ai" "$ST/log"'
check "agents install: uv-based (kimi)"     sh -c 'aleph agents install kimi --host gpu2 --yes </dev/null >/dev/null 2>&1 && grep -q "^uv tool install kimi-cli" "$ST/log" && aleph --host gpu2 agents --json </dev/null | jq -e "[.hosts[0].agents[] | select(.id==\"kimi\")][0].installed"; r=$?; rm -f "$RHOME/.local/bin/kimi"; exit $r'
check "splash: an unknown name lists them; no tty refuses; a bad --ms says why" sh -c 'o=$(aleph splash nosuch </dev/null 2>&1); [ $? -ne 0 ] && printf "%s" "$o" | grep -q "theme, cockpit" && printf "%s" "$o" | grep -q singularity && o=$(aleph splash theme </dev/null 2>&1); [ $? -ne 0 ] && printf "%s" "$o" | grep -q "on a terminal" && o=$(aleph splash singularity --ms 2s </dev/null 2>&1); [ $? -ne 0 ] && printf "%s" "$o" | grep -q "on a terminal" && ! aleph splash --ms soon </dev/null >/dev/null 2>&1'
check "splash: ui.splash_ms is auto or 1–8 s; random is a splash" sh -c '! aleph settings set ui.splash_ms 12s </dev/null >/dev/null 2>&1 && aleph settings set ui.splash_ms 4s </dev/null >/dev/null && aleph settings set ui.splash random </dev/null >/dev/null; r=$?; aleph settings unset ui.splash_ms </dev/null >/dev/null 2>&1; aleph settings unset ui.splash </dev/null >/dev/null 2>&1; exit $r'
check "a setting the profile names changes in the profile" sh -c 'aleph profile use demo </dev/null >/dev/null 2>&1 && aleph settings set ui.splash neon </dev/null >/dev/null && [ "$(aleph settings get ui.splash </dev/null)" = neon ] && grep -q neon "$HOME/.config/aleph/profiles/demo.toml" && ! grep -qs "neon" "$HOME/.config/aleph/aleph.toml"; r=$?; aleph profile off </dev/null >/dev/null 2>&1; exit $r'
check "settings rejects an unknown agent"   sh -c '! aleph settings set agent clade </dev/null && aleph settings set agent codex </dev/null'
check "update --check: gpu2 herdr is behind" sh -c 'aleph update --check </dev/null | grep -q "gpu2.*0.8.0.*behind"'
check "update --json: status and lag"       sh -c 'aleph update --json </dev/null | jq -e "(.hosts[] | select(.alias==\"gpu2\") | .herdr_status==\"behind\") and (.hosts[] | select(.alias==\"b31\") | .herdr_status==\"same\")"'
check "update --check changes nothing"      sh -c '! grep -q "herdr update" "$ST/log"'
check "inbox: a closed session is an event" sh -c 'aleph inbox --json </dev/null | jq -e "[.[] | select(.host==\"gpu2\" and .name==\"weave\" and .kind==\"gone\")] | length == 1"'
check "inbox piped is TSV"                  sh -c 'aleph inbox </dev/null | awk -F"\t" "NF==5" | grep -q "gone"'
check "host.<m>.session: herdr's named session on every call there" sh -c 'aleph settings set host.b31.session bench </dev/null >/dev/null; : > "$ST/log"; aleph --host b31 ls --json </dev/null >/dev/null 2>&1; r=1; grep -q "export HERDR_SESSION=bench; " "$ST/log" && ! grep "gpu2" "$ST/log" | grep -q HERDR_SESSION && r=0; aleph settings unset host.b31.session </dev/null >/dev/null; exit $r'
check "inbox: read, dismiss, --all"         sh -c 'aleph inbox read --json </dev/null | jq -e ".seen > 0" >/dev/null && id=$(aleph inbox --json </dev/null | jq -r ".[0].id") && aleph inbox dismiss "$id" --json </dev/null | jq -e ".dismissed == 1" >/dev/null && ! aleph inbox --json </dev/null | jq -e --arg i "$id" "any(.[]; .id == \$i)" >/dev/null && aleph inbox --all --json </dev/null | jq -e --arg i "$id" "any(.[]; .id == \$i and .archived)" >/dev/null'
check "sessions.json remembers sessions"    sh -c 'jq -e "[.sessions[] | select(.host==\"b31\")] | length >= 2" "$XDG_STATE_HOME/aleph/sessions.json"'
check "restore --dry-run: nothing lost yet" sh -c 'aleph restore --dry-run </dev/null 2>&1 | grep -q "nothing to restore"'
check "restore --dry-run after a restart"   sh -c 'cp "$ST/agents_b31.json" "$ST/agents_b31.bak"; echo "{\"result\":{\"agents\":[]}}" > "$ST/agents_b31.json"; aleph restore --dry-run --json </dev/null | jq -e "[.[] | select(.host==\"b31\" and .agent==\"codex\")] | length == 1 and ([.[] | select(.agent==\"claude\")] | length == 0)"'
check "restore --yes resumes the agent"     sh -c 'aleph restore --yes </dev/null && grep -q "agent start .* --kind codex .* -- resume --last" "$ST/log"; r=$?; cp "$ST/agents_b31.bak" "$ST/agents_b31.json"; exit $r'
check "restore continues the same conversation" sh -c 'cp "$ST/agents_b31.json" "$ST/agents_b31.bak"; echo "{\"result\":{\"agents\":[]}}" > "$ST/agents_b31.json"; aleph restore --dry-run --json --all </dev/null | jq -e "[.[] | select(.name==\"ignite\")][0].args == [\"--resume\",\"3f2a9c1e-0b7d-4c55-9a61-2e8f0c4d7a10\"]" >/dev/null; r=$?; cp "$ST/agents_b31.bak" "$ST/agents_b31.json"; exit $r'
check "agent_wrapper: herdr still knows the agent" sh -c 'aleph settings set agent_wrapper "nono run --" </dev/null >/dev/null; : > "$ST/log"; aleph --host b31 new --agent claude --name wrapped --detach </dev/null >/dev/null 2>&1; r=$?; aleph settings unset agent_wrapper </dev/null >/dev/null; [ $r -eq 0 ] && grep -q "pane run .*HERDR_AGENT=claude nono run -- claude" "$ST/log" && grep -q "report-metadata .*--display-agent Claude Code" "$ST/log"'
check "agent_wrapper: a missing sandbox is refused, nothing typed" sh -c 'aleph settings set agent_wrapper "no-such-sandbox run --" </dev/null >/dev/null; : > "$ST/log"; aleph --host b31 new --agent codex --name boxed --detach </dev/null >/dev/null 2>"$ST/wrap.err"; r=$?; aleph settings unset agent_wrapper </dev/null >/dev/null; [ $r -ne 0 ] && grep -q "no-such-sandbox. isn.t installed on b31" "$ST/wrap.err" && ! grep -q "HERDR_AGENT=codex" "$ST/log"'
check "piped unknown args go to Claude Code" sh -c 'echo hi | ALEPH_WRAP=1 aleph -p "say hi" | grep -q "LOCAL-CLAUDE -p"'
check "Claude Code subcommands pass through" sh -c 'ALEPH_WRAP=1 aleph mcp list </dev/null | grep -q "LOCAL-CLAUDE mcp list"'
check "completions for zsh/bash/fish"        sh -c 'aleph completions zsh </dev/null | grep -q "compdef _aleph aleph" && aleph completions bash </dev/null | grep -q "complete -o default -F" && aleph completions fish --name cc </dev/null | grep -q "complete -c cc"'
check "theme --json has machines and hues"   sh -c 'aleph theme --json </dev/null | jq -e "(.machines | length == 2) and (.hues | length == 12)"'
check "theme herdr --apply writes the block" sh -c 'aleph theme herdr --apply </dev/null && grep -q "^\[ui.sidebar.agents\]" "$HOME/.config/herdr/config.toml" && aleph theme herdr --apply </dev/null 2>&1 | grep -q already'
check "theme machines --apply sets accents"  sh -c 'mkdir -p "$RHOME/.config/herdr" && printf "# mine\n[ui]\nx = 1\n" > "$RHOME/.config/herdr/config.toml" && aleph --host b31 theme machines --apply </dev/null && grep -q "^accent = \"#89b4fa\"" "$RHOME/.config/herdr/config.toml" && grep -q "^# mine" "$RHOME/.config/herdr/config.toml" && [ "$(grep -c "^\[ui\]" "$RHOME/.config/herdr/config.toml")" = 1 ] && grep -q "herdr --machine b31 server reload-config" "$ST/log"'
check "shortcuts install + ls"               sh -c 'aleph shortcuts install </dev/null && [ -x "$HOME/.raycast-scripts/aleph-gpu2.sh" ] && grep -q "aleph --host b31" "$HOME/.warp/tab_configs/aleph_b31.toml" && aleph shortcuts ls --json </dev/null | jq -e "all(.[]; .state == \"managed\")"'
check "shortcuts never overwrite your files" sh -c 'echo mine > "$HOME/.warp/tab_configs/aleph_b31.toml"; aleph shortcuts install </dev/null; [ "$(cat "$HOME/.warp/tab_configs/aleph_b31.toml")" = mine ]'
check "watch --once notifies + status.json"  sh -c 'aleph watch --once </dev/null && grep -Eq "(terminal-notifier|notify-send).*temper" "$ST/log" && jq -e ".blocked == 1" "$XDG_CACHE_HOME/aleph/status.json"'
check "watch --install --dry-run"            sh -c 'aleph watch --install --dry-run </dev/null | grep -Eq "dev.aleph.daemon|aleph.service" && ! grep -Eq "^(launchctl|systemctl)" "$ST/log"'
check "self-update --check"                  sh -c 'echo "{\"tag_name\":\"v99.0.0\",\"assets\":[]}" > "$ST/rel.json" && ALEPH_UPDATE_URL="file://$ST/rel.json" aleph settings set update_repo me/aleph </dev/null && ALEPH_UPDATE_URL="file://$ST/rel.json" aleph self-update --check --json </dev/null | jq -e ".update_available and .latest == \"99.0.0\""'
check "new --detach --json starts without a tty" sh -c 'aleph --host b31 new --dir /home/selene/ox_meadow --detach --json </dev/null | jq -e ".name != null and .pane_id != null and .host == \"b31\""'
check "peek --json reads recent output"       sh -c 'aleph peek b31:temper --json </dev/null | jq -e ".name == \"temper\" and (.text | contains(\"TensorRT\"))"'
check "peek --ansi keeps the colours"         sh -c 'aleph peek b31:temper --json --ansi </dev/null | jq -e "(.text | contains(\"\\u001b[38;2;217;119;87m\")) and (.text | contains(\"TensorRT\"))"'
check "peek of a blocked session has the question" sh -c 'aleph peek temper --json </dev/null | jq -e ".question | contains(\"Do you want\")"'
check "stats --json samples every machine"    sh -c 'aleph stats --json </dev/null | jq -e "[.hosts[] | select(.reachable)] | length == 2"'
check "local codex starts in this herdr, here" sh -c 'aleph settings set local true </dev/null >/dev/null && cd "$RHOME/blaze" && aleph local codex --detach --json </dev/null | jq -e ".host == \"local\" and (.sessions[0].dir | endswith(\"blaze\"))" && grep -q "^herdr agent start .* --kind codex" "$ST/log" && ! grep -q "^herdr --machine local" "$ST/log"'
check "ls --json shows the local machine"     sh -c 'aleph ls --json </dev/null | jq -e "[.hosts[] | select(.alias==\"local\" and .reachable)] | length == 1"'
check "local shell opens a tab without an agent" sh -c 'n=$(grep -c "^herdr agent start" "$ST/log"); aleph local shell --detach </dev/null >/dev/null 2>&1 && [ "$(grep -c "^herdr agent start" "$ST/log")" = "$n" ]; r=$?; aleph settings set local false </dev/null >/dev/null; exit $r'
check "approve picks the yes option"          sh -c 'aleph approve b31:temper --json </dev/null | jq -e ".keys == [\"1\"]" && grep -q "agent send-keys w1:p2 1" "$ST/log"'
check "approve refuses when nothing is asked" sh -c '! aleph approve b31:ignite </dev/null 2>/dev/null'
check "ls --json has herdr versions + drift"  sh -c 'aleph ls --json </dev/null | jq -e "(.hosts[] | select(.alias==\"b31\") | .herdr_version==\"0.9.5\" and (.herdr_drift|not)) and (.hosts[] | select(.alias==\"gpu2\") | .herdr_drift == (.herdr_version != \"0.9.5\"))"'
check "queue add / ls / rm"                  sh -c 'id=$(aleph queue add b31 "tidy the README" --json </dev/null | jq -r .id) && aleph queue ls --json </dev/null | jq -e "[.[] | select(.state==\"queued\")] | length == 1" && aleph queue rm $id </dev/null && aleph queue ls --json </dev/null | jq -e "[.[] | select(.state==\"queued\")] | length == 0"'
check "queue: an idle agent gets the task"   sh -c 'A="$ST/agents_b31.json"; cp "$A" "$A.q"; jq ".result.agents += [{\"pane_id\":\"w1:p77\",\"tab_id\":\"w1:t77\",\"agent\":\"claude\",\"agent_status\":\"idle\",\"cwd\":\"/srv/q\",\"name\":\"qtest\",\"tokens\":{}}]" "$A.q" > "$A"; aleph queue add b31 "say hi" --dir /srv/q </dev/null >/dev/null; aleph watch --interval 5 </dev/null >/dev/null 2>&1 & p=$!; sleep 7; kill $p; cp "$A.q" "$A"; grep -q "PROMPT w1:p77 say hi" "$ST/log" && aleph queue ls --json </dev/null | jq -e ".[] | select(.prompt==\"say hi\") | .state==\"sent\" and .session==\"qtest\"" >/dev/null && aleph inbox --json </dev/null | jq -e "[.[] | select(.kind==\"task\")] | length >= 1"'
check "auto rules: match, deny, no-yes"      sh -c 'aleph auto add bench "*cargo bench*" </dev/null >/dev/null && aleph auto test "Do you want to run cargo bench --quick?\n ❯ 1. Yes\n   2. No" </dev/null && ! aleph auto test "run rm -rf / ? ❯ 1. Yes" </dev/null 2>/dev/null && ! aleph auto test "which trtexec flags?" </dev/null 2>/dev/null && aleph auto --json </dev/null | jq -e ".rules[0].name==\"bench\" and (.on|not)"'
check "notify test posts to every sink"      sh -c 'aleph settings set notify.ntfy https://ntfy.sh/cc-smoke </dev/null >/dev/null && aleph settings set notify.webhook http://127.0.0.1:9/fail </dev/null >/dev/null; ! aleph notify test </dev/null >/dev/null 2>&1 && grep -qE "priority.{1,4}4" "$ST/log" && grep -qE "topic.{1,6}cc-smoke" "$ST/log" && grep -q "url = .https://ntfy.sh.$" "$ST/log" && grep -q "curl .*127.0.0.1:9/fail" "$ST/log"; r=$?; aleph settings unset notify.webhook </dev/null >/dev/null; exit $r'
# every agent, not just Claude Code: defaults, launch, filters, passthrough, doctor, onboarding
check "new --detach starts the default agent (codex), unfocused" sh -c 'aleph settings set agent codex </dev/null >/dev/null && aleph --host b31 new --detach --json </dev/null | jq -e ".agent == \"codex\" and (.sessions[0].label | startswith(\"codex_\"))" >/dev/null && grep -q "^herdr agent start .* --kind codex --pane" "$ST/log" && grep -q "^herdr tab create .*--no-focus" "$ST/log"'
check "an agent without a herdr kind is typed in" sh -c 'aleph --host gpu2 new --agent crush --detach </dev/null >/dev/null && grep -Eq "^herdr pane run w1:p[0-9]+ crush$" "$ST/log"'
check "agents=codex lists only codex sessions"  sh -c 'aleph settings set agents codex </dev/null >/dev/null && aleph ls --json </dev/null | jq -e "[.hosts[].sessions[].agent] | length > 0 and all(. == \"codex\")" >/dev/null; r=$?; aleph settings set agents all </dev/null >/dev/null; exit $r'
check "agents= rejects an unknown agent"       sh -c '! aleph settings set agents claude,clade </dev/null 2>/dev/null && aleph settings set agents claude,codex </dev/null >/dev/null && aleph settings set agents all </dev/null >/dev/null'
check "wraps: passthrough to the shadowed agent" sh -c 'mkdir -p "$ST/lbin" && printf "#!/bin/sh\n[ \"\$1\" = --help ] && { printf \"Usage: codex\\\\n\\\\nCommands:\\\\n  exec  Run non-interactively\\\\n\"; exit 0; }\necho \"LOCAL-CODEX \$*\"\n" > "$ST/lbin/codex" && chmod +x "$ST/lbin/codex" && aleph settings set wraps codex </dev/null >/dev/null && PATH="$ST/lbin:$PATH" ALEPH_WRAP=1 aleph exec hi </dev/null | grep -q "LOCAL-CODEX exec hi" && grep -qx exec "$XDG_CACHE_HOME/aleph/codex-commands" && PATH="$ST/lbin:$PATH" aleph help </dev/null | grep -q "run your local Codex"; r=$?; aleph settings unset wraps </dev/null >/dev/null; exit $r'
check "wraps=claude still reaches Claude Code"  sh -c 'ALEPH_WRAP=1 aleph mcp list </dev/null | grep -q "LOCAL-CLAUDE mcp list"'
check "ALEPH_NO_PASSTHROUGH refuses"     sh -c 'ALEPH_WRAP=1 ALEPH_NO_PASSTHROUGH=1 aleph mcp list </dev/null 2>&1 | grep -q "passthrough refused"; [ $? -eq 0 ] && { ALEPH_WRAP=1 ALEPH_NO_PASSTHROUGH=1 aleph mcp list </dev/null >/dev/null 2>&1; [ $? -eq 97 ]; }'
check "doctor checks every agent on the machine" sh -c 'aleph doctor --json </dev/null | jq -e "[.sections[] | select(.section==\"On b31\") | .checks[].label] | (index(\"Claude Code\") != null) and (index(\"Codex\") != null) and (index(\"herdr\") != null)" >/dev/null'
check "doctor fails a default agent that's missing" sh -c 'aleph settings set agent maki </dev/null >/dev/null && aleph doctor --json </dev/null | jq -e "[.sections[] | select(.section==\"On b31\") | .checks[] | select(.label==\"Maki\" and .status==\"fail\")] | length == 1" >/dev/null; r=$?; aleph settings set agent codex </dev/null >/dev/null; exit $r'
check "onboarding shows the agents it found"    sh -c 'aleph host include gpu2 </dev/null 2>&1 | grep -q "agents.*Claude Code 2.1.200 · Codex 0.40.1"'
check "help speaks of agent sessions"           sh -c 'aleph help </dev/null | grep -q "Agent sessions inside herdr"'
# local LLM servers and gateways (simulated machines: tests/fixtures/services)
check "services --json: b31's servers, not its traps" sh -c 'aleph services --json </dev/null | jq -e "(.hosts[] | select(.alias==\"b31\") | [.services[].id]) == [\"ollama\",\"vllm\",\"tgi\",\"sglang\",\"triton\",\"litellm\"] and ([.hosts[] | select(.alias==\"b31\") | .services[].ports[]] | map(select(. == 30000 or . == 8001 or . == 5000 or . == 1234 or . == 6006)) | length == 0)"'
check "services --json: every kind on gpu2"   sh -c 'aleph services --json </dev/null | jq -e "(.hosts[] | select(.alias==\"gpu2\") | [.services[].id]) == [\"llamacpp\",\"localai\",\"koboldcpp\",\"tabbyapi\",\"aphrodite\",\"xinference\",\"trtllm\",\"llamaswap\",\"tgwebui\",\"openwebui\"]"'
check "services --json: models, VRAM, load"   sh -c 'aleph services --json </dev/null | jq -e ".hosts[] | select(.alias==\"b31\") | .services[] | select(.id==\"vllm\") | .health==\"up\" and .vram > 4e10 and .models[0].loaded and .requests_running==2 and .url==\"http://127.0.0.1:8000\" and .found_by==[\"process\",\"http\"]" >/dev/null && aleph services --json </dev/null | jq -e ".hosts[] | select(.alias==\"b31\") | .services[] | select(.id==\"ollama\") | .loaded_count==1 and .model_count==3 and .pid==1200"'
check "services piped is TSV"                 sh -c 'aleph services </dev/null 2>/dev/null | awk -F"\t" "NF==10" | grep -q "^gpu2	llamacpp	llama.cpp		8080	loading	1	0"'
check "services rides the shared ssh, read-only" sh -c 'grep -Eq "^ssh -T .*BatchMode=yes.* b31 sh -s" "$ST/log" && ! grep -Eq "^ssh .*(ollama|vllm) (serve|pull|run)" "$ST/log"'
check "services=off: says how to go live"      sh -c 'aleph services </dev/null 2>&1 >/dev/null | grep -q "settings set services on" && aleph services --json </dev/null | jq -e ".enabled == false and .interval == 30"'
check "service.<id>=off skips one"             sh -c 'aleph settings set service.vllm off </dev/null >/dev/null && aleph services --json </dev/null | jq -e "[.hosts[].services[].id] | index(\"vllm\") == null" >/dev/null; r=$?; aleph settings unset service.vllm </dev/null >/dev/null; exit $r'
check "services settings are checked"          sh -c '! aleph settings set services maybe </dev/null 2>/dev/null && ! aleph settings set service.olama off </dev/null 2>/dev/null && aleph settings set services on </dev/null >/dev/null && aleph services --json </dev/null | jq -e ".enabled" >/dev/null; r=$?; aleph settings set services off </dev/null >/dev/null; exit $r'
check "services --host local (a simulated Mac)" sh -c 'ALEPH_SERVICES_FIXTURES="$ST/svc_mac" aleph services --host local --json </dev/null | jq -e "[.hosts[0].services[].id] == [\"ollama\",\"lmstudio\",\"jan\",\"mlxlm\",\"gpt4all\"] and .hosts[0].listeners == \"lsof\""'
check "services: an unreachable machine is an error" sh -c 'echo refused > "$ST/mode_gpu2"; aleph services --json </dev/null | jq -e "(.hosts[] | select(.alias==\"gpu2\") | .reachable==false and (.error | contains(\"refused\"))) and (.hosts[] | select(.alias==\"b31\") | .reachable)"; r=$?; rm -f "$ST/mode_gpu2"; exit $r'
check "help services"                          sh -c 'aleph help services </dev/null | grep -q "never by a port number alone" && aleph help </dev/null | grep -q "aleph services"'
# token analytics from the agents' own logs (synthetic: tests/fixtures/usage)
check "usage sync reads both machines"        sh -c 'aleph usage sync --json </dev/null | jq -e ".hosts | length == 2 and all(.[]; .ok and .records >= 13 and .files_read >= 6)"'
check "usage --json: every agent, with costs" sh -c 'aleph usage all --by agent --json </dev/null | jq -e "([.rows[].key] | (index(\"claude\") != null) and (index(\"codex\") != null) and (index(\"pi\") != null) and (index(\"gemini\") != null) and (index(\"opencode\") != null)) and .total.requests >= 26 and .total.sessions >= 12 and .total.cost > 0 and (.unpriced_models | length == 0)"'
check "usage --by host: a row per machine"    sh -c 'aleph usage all --by host --json </dev/null | jq -e "[.rows[].key] == [\"b31\",\"gpu2\"]"'
check "usage piped is TSV, --csv is CSV"      sh -c 'aleph usage all --by model </dev/null | head -1 | grep -q "^key	input	output	cache_read" && aleph usage all --by model </dev/null | grep -q "^claude-opus-5-5	" && aleph usage all --by day --csv </dev/null | grep -Eq "^2026-10-2[12] [A-Z][a-z]{2},"'
check "usage keeps no conversation text"      sh -c '[ -n "$(ls "$XDG_STATE_HOME/aleph/usage/" | grep records-)" ] && ! grep -rq SECRET "$XDG_STATE_HOME/aleph/usage"'
check "usage accounts: each login its own, never a credential" sh -c 'o=$(aleph usage accounts --json </dev/null) && printf "%s" "$o" | jq -e "[.accounts[] | select(.agent==\"claude\") | .email] | (index(\"u@home.example\") != null) and (index(\"u@work.example\") != null)" >/dev/null && printf "%s" "$o" | jq -e "[.accounts[] | select(.agent==\"claude\" and .email==\"u@work.example\")][0] | .plan == \"Max 20x\" and (.hosts | length) == 2 and (.id | length) == 6" >/dev/null && printf "%s" "$o" | jq -e "any(.accounts[]; .agent==\"codex\" and .usage_30d.requests > 0)" >/dev/null && ! printf "%s" "$o" | grep -q SECRET && ! grep -rq SECRET "$XDG_STATE_HOME/aleph/usage" && ! grep -q "credentials.json\|auth.json\|oauth_creds" "$ST/log"'
check "usage --stats: per prompt and per session" sh -c 'aleph usage all --stats --json </dev/null | jq -e ".stats.prompt_cost.n >= 4 and .stats.prompt_cost.p50 > 0 and (.stats.prompt_cost.buckets | length) > 0 and .stats.top_prompts[0].requests >= 1 and .stats.session_cost.n >= 8 and .total.prompts >= 4 and (.rows | all(has(\"cost_per_prompt\")))" >/dev/null'
check "usage periods, lists and the period before" sh -c 'aleph usage 24h --json </dev/null | jq -e ".range.label == \"last 24 hours\"" >/dev/null && aleph usage this-week --json </dev/null | jq -e ".range.label == \"this week\" or .range.label == \"today\"" >/dev/null && aleph usage 2026-10-01..2026-10-31 --by day --json </dev/null | jq -e "(.rows | length) >= 1 and .range.from == \"2026-10-01\"" >/dev/null && aleph usage all --agent claude,codex --by agent --json </dev/null | jq -e "[.rows[].key] | sort == [\"claude\",\"codex\"]" >/dev/null && aleph usage 7d --compare --json </dev/null | jq -e ".previous.range | test(\"–\")" >/dev/null && ! aleph usage 2026-13-01.. </dev/null 2>/dev/null && aleph usage all --by hour --json </dev/null | jq -e ".rows[0].key | test(\"^2026-10-2[0-9] [0-9][0-9]$\")" >/dev/null'
check "usage projects: one repo across its folders, never its password" sh -c 'aleph usage sync --json </dev/null >/dev/null; o=$(aleph usage projects all --json </dev/null) && printf "%s" "$o" | jq -e "[.projects[] | select(.remote == \"github.com/acme/app\")] | length == 1 and .[0].name == \"app\" and ([.[0].machines[].folders[]] | unique | length) == 3 and (.[0].machines | length) == 2 and .[0].usage.requests == 6" >/dev/null && aleph usage all --project app --by folder --json </dev/null | jq -e "[.rows[].key] | sort == [\"~/src/app\",\"~/src/app-wt\",\"~/src/copy\"]" >/dev/null && aleph usage all --by project --json </dev/null | jq -e "any(.rows[]; .label == \"app\")" >/dev/null && ! grep -rq SECRET-ghp "$XDG_STATE_HOME/aleph/usage" && ! grep -q SECRET-ghp "$ST/log"'
check "timeline: prompts, turns, tool calls, a subagent — names and numbers kept, words only live" sh -c 'U="$XDG_STATE_HOME/aleph/usage"; aleph usage sync --json </dev/null >/dev/null; [ -n "$(ls "$U" | grep "^steps-")" ] && ! grep -rq SECRET "$U" && o=$(aleph timeline 3f2a9c1e --host b31 --fold open --json </dev/null) && printf "%s" "$o" | jq -e "(.lanes | length) == 2 and any(.rows[]; .label == \"Explore agent\") and any(.rows[]; .kind == \"tool\" and (.label | startswith(\"Bash\"))) and any(.rows[]; .kind == \"error\") and .sums.requests == 4" >/dev/null && w=$(aleph timeline 7a7a --host b31 --words --json </dev/null) && printf "%s" "$w" | jq -e "(.words | length) >= 2 and ([.words[]] | any(test(\"SECRET command\")))" >/dev/null && ! grep -rq SECRET "$U" && aleph timeline ls </dev/null | grep -q "^b31	claude" && aleph timeline 7a7a --host b31 </dev/null 2>/dev/null | grep -q "prompt 1"'
check "usage --explore: the cost broken up under the total, the week's hours, the stats; timeline ls with projects and cost" sh -c 'o=$(aleph usage 30d --explore --no-sync --json </dev/null) && printf "%s" "$o" | jq -e ".explore.split == \"account\" and (.explore.breakup | length) >= 1 and (.explore.heat.cost | length) == 7 and (.explore.heat.cost[0] | length) == 24 and (.explore.stats.prompt_cost | has(\"p90\")) and ((.explore.breakup | map(.cost) | add) - .total.cost | fabs) < 0.01" >/dev/null && aleph usage 30d --explore --by agent --no-sync --json </dev/null | jq -e ".explore.split == \"agent\" and any(.explore.breakup[]; .key == \"claude\")" >/dev/null && aleph timeline ls --json -n 3 </dev/null | jq -e "length >= 1 and all(.[]; has(\"project\") and has(\"cost\"))" >/dev/null && ! aleph usage 30d --explore --by nonsense --no-sync --json </dev/null 2>/dev/null | jq -e ".explore.split == \"nonsense\"" >/dev/null'
check "usage reads every log again once for the timeline, never counting twice" sh -c 'U="$XDG_STATE_HOME/aleph/usage"; t0=$(aleph usage all --json </dev/null | jq .total.requests); n0=$(cat "$U"/records-*.tsv | wc -l); echo "{}" > "$U/gens.json"; aleph usage sync --json </dev/null >/dev/null; t1=$(aleph usage all --json </dev/null | jq .total.requests); n1=$(cat "$U"/records-*.tsv | wc -l); [ "$t0" = "$t1" ] && [ "$n0" = "$n1" ] && jq -e "all(.[]; .gen == 2 and (.catching_up | not))" "$U/gens.json" >/dev/null'
check "usage --by account and --account"     sh -c 'aleph usage all --by account --json </dev/null | jq -e "[.rows[].label] | any(test(\"u@work.example\"))" >/dev/null && aleph usage all --account u@work.example --by agent --json </dev/null | jq -e ".rows | length == 1 and .[0].key == \"claude\" and .[0].requests == 4" >/dev/null && ! aleph usage --account nobody@x </dev/null 2>/dev/null'
check "usage sync again reads nothing new"    sh -c 'aleph usage sync --json </dev/null | jq -e "all(.hosts[]; .ok and .records == 0)"'
check "usage sources: what each machine gave" sh -c 'aleph usage sources --json </dev/null | jq -e "[.hosts[].last_run.agents[] | select(.agent==\"claude\") | .roots | length] | (length == 2) and all(. > 0)" >/dev/null && aleph usage sources </dev/null | grep -q "claude"'
check "usage script carries the offsets"      sh -c 'aleph usage script --host b31 </dev/null | grep -q "never any message text" && aleph usage script --host b31 </dev/null | grep -q "^K	.*rollout-"'
check "usage off/on --host scopes a machine"  sh -c 'aleph usage off --host gpu2 </dev/null 2>/dev/null && aleph usage sync --json </dev/null | jq -e "[.hosts[] | select(.host==\"gpu2\")][0].excluded" >/dev/null && aleph usage all --by host --json </dev/null | jq -e "[.rows[].key] == [\"b31\"]" >/dev/null; r=$?; aleph usage on --host gpu2 </dev/null 2>/dev/null; exit $r'
check "usage settings are checked"            sh -c '! aleph settings set analytics.backfill soon </dev/null 2>/dev/null && ! aleph settings set analytics.prices.gpt-6 lots </dev/null 2>/dev/null && aleph settings set analytics.prices.gpt-6 2,16 </dev/null >/dev/null && aleph settings unset analytics.prices.gpt-6 </dev/null >/dev/null'
check "usage prune: --dry-run changes nothing" sh -c 'aleph usage prune --dry-run </dev/null 2>&1 | grep -q "nothing to prune" && aleph usage prune --host gpu2 --dry-run --json </dev/null | jq -e ".dry_run and .records_removed >= 13" >/dev/null && aleph usage all --by host --json </dev/null | jq -e ".rows | length == 2"'
check "help usage"                            sh -c 'aleph help usage </dev/null | grep -q "never conversation text" && aleph help </dev/null | grep -q "aleph usage"'
check "offline machine keeps cached sessions" sh -c 'echo refused > "$ST/mode_gpu2"; rm -f "$ST/up_gpu2"; aleph ls --json </dev/null | jq -e ".hosts[] | select(.alias==\"gpu2\") | .reachable==false and .error!=null"'
check "doctor checks every machine side by side" sh -c 'aleph doctor --json </dev/null | jq -e "[.sections[].section] | (index(\"On b31\") != null) and (index(\"Host · gpu2\") != null)" >/dev/null && aleph --host gpu2 doctor --json </dev/null | jq -e "[.sections[].section] | index(\"On b31\") == null" >/dev/null'
check "doctor --json is valid"               sh -c 'aleph doctor --json </dev/null | jq -e ".sections | length > 0" >/dev/null; [ $? -eq 0 ]'

# --- aleph.toml
check "config: the old file became aleph.toml"  sh -c '[ -f "$HOME/.config/aleph/aleph.toml" ] && [ -f "$HOME/.config/aleph/config.bak" ] && grep -q "^\[fleet\]" "$HOME/.config/aleph/aleph.toml"'
check "config check passes"                     sh -c 'aleph config check </dev/null >/dev/null'
check "config check names a typo"               sh -c 'cp "$HOME/.config/aleph/aleph.toml" "$ST/t.bak"; printf "\n[uii]\nscale = 1\n" >> "$HOME/.config/aleph/aleph.toml"; aleph config check </dev/null 2>&1 | grep -q "did you mean"; r=$?; cp "$ST/t.bak" "$HOME/.config/aleph/aleph.toml"; exit $r'
check "config export masks secrets"             sh -c 'aleph settings set notify.ntfy https://ntfy.sh/topsecret9 </dev/null >/dev/null; aleph config export </dev/null | grep -q "^\[fleet\]" && ! aleph config export </dev/null | grep -q topsecret9; r=$?; aleph settings unset notify.ntfy </dev/null >/dev/null; exit $r'
check "config import --dry-run shows changes"   sh -c 'printf "[ui]\nscale = \"large\"\n" > "$ST/team.toml" && aleph config import "$ST/team.toml" --dry-run </dev/null 2>&1 | grep -q "ui_scale" && [ "$(aleph settings get ui_scale </dev/null)" != large ]'
check "config sources + schema"                 sh -c 'aleph config sources ui_scale </dev/null | grep -q "default" && aleph config schema </dev/null | jq -e ".properties.ui.properties.scale.enum | length > 1" >/dev/null'
check "secret: references resolve, never export" sh -c 'aleph secret set ntfy-smoke https://ntfy.sh/zz-secret </dev/null >/dev/null && aleph settings set notify.ntfy secret:ntfy-smoke </dev/null >/dev/null && : > "$ST/log" && aleph notify test </dev/null >/dev/null 2>&1; grep -qE "topic.{1,6}zz-secret" "$ST/log" && ! aleph config export </dev/null | grep -q zz-secret && aleph config export </dev/null | grep -q "secret:ntfy-smoke"; r=$?; aleph settings unset notify.ntfy </dev/null >/dev/null; aleph secret rm ntfy-smoke </dev/null >/dev/null; exit $r'
# --- logs
check "logs record external commands at debug"  sh -c 'ALEPH_LOG=debug aleph ls --json </dev/null >/dev/null && aleph logs --level debug -n 400 </dev/null | grep -q " proc: "'
check "logs never keep a notification URL"      sh -c 'aleph settings set notify.ntfy https://ntfy.sh/topsecret123 </dev/null >/dev/null; ALEPH_LOG=debug aleph notify test </dev/null >/dev/null 2>&1; aleph settings unset notify.ntfy </dev/null >/dev/null; ! grep -q topsecret123 "$XDG_STATE_HOME/aleph/aleph.log"'
check "logs --bundle"                           sh -c 'aleph logs --bundle </dev/null 2>&1 | grep -q "bug report bundle"'
# --- Moshi (fake moshi-hook: paired, claude hooked natively here); off by
# default, so these turn it on (auto: on because it's paired) and back off
aleph settings set moshi auto </dev/null >/dev/null
check "moshi status --json"                    sh -c 'aleph moshi status --json </dev/null | jq -e ".paired and .running and .native_agents == [\"claude\"] and .bridge"'
check "moshi test sends a card"                sh -c ': > "$ST/log"; aleph moshi test </dev/null && grep -q "moshi-hook notify --source aleph" "$ST/log"'
check "moshi: blocked + no remote.allow → card" sh -c ': > "$ST/log"; aleph moshi sync </dev/null >/dev/null && grep -q "moshi-hook notify .*temper needs you" "$ST/log" && ! grep -q "moshi-hook ask" "$ST/log"'
check "moshi: approval from the phone"         sh -c 'aleph settings set remote.allow "b31:*" </dev/null >/dev/null && : > "$ST/log" && aleph moshi sync </dev/null >/dev/null; r=$?; aleph settings unset remote.allow </dev/null >/dev/null; [ $r -eq 0 ] && grep -q "moshi-hook ask --require-remote" "$ST/log" && grep -q "agent send-keys w1:p2 1" "$ST/log" && aleph inbox -n 5 --json </dev/null | jq -e "any(.[]; .title | test(\"answered from Moshi\"))"'
check "moshi: Deny on the phone picks the agent's own no" sh -c 'aleph settings set remote.allow "*:*" </dev/null >/dev/null && echo deny > "$ST/moshi_answer" && : > "$ST/log" && aleph moshi sync </dev/null >/dev/null; rm -f "$ST/moshi_answer"; aleph settings unset remote.allow </dev/null >/dev/null; grep -q "moshi-hook ask" "$ST/log" && grep -q "Deny answers" "$ST/log" && ! grep -q "moshi-hook ask.*--option" "$ST/log" && grep -q "agent send-keys w1:p2 3" "$ST/log" && ! grep -q "agent send-keys w1:p2 1" "$ST/log"'
check "moshi.choices: the agent's options as buttons" sh -c 'aleph settings set remote.allow "b31:*" </dev/null >/dev/null && aleph settings set moshi.choices true </dev/null >/dev/null && : > "$ST/log" && aleph moshi sync </dev/null >/dev/null; aleph settings unset moshi.choices </dev/null >/dev/null; aleph settings unset remote.allow </dev/null >/dev/null; grep -q "moshi-hook ask.*--option" "$ST/log" && grep -q "agent send-keys w1:p2 1" "$ST/log"'
check "moshi: working sessions get job rows"   sh -c ': > "$ST/log"; aleph moshi sync </dev/null >/dev/null && grep -q "moshi-hook job start --source aleph" "$ST/log"'
check "moshi usage --json"                     sh -c 'aleph moshi usage --json </dev/null | jq -e ".[0].used == 42"'
check "moshi: a machine's own moshi-hook → machine news only" sh -c 'echo "{\"paired\":true,\"hooks\":[{\"target\":\"claude\",\"status\":\"current\"}]}" > "$ST/moshi_remote_b31"; aleph agents --host b31 --refresh </dev/null >/dev/null 2>&1; : > "$ST/log"; aleph moshi sync </dev/null >/dev/null; r=$?; d=$(aleph doctor --host b31 </dev/null 2>&1); rm -f "$ST/moshi_remote_b31"; aleph agents --host b31 --refresh </dev/null >/dev/null 2>&1; [ $r -eq 0 ] && ! grep -q "moshi-hook notify .*temper needs you" "$ST/log" && printf "%s" "$d" | grep -q "moshi-hook.*tells the phone about claude"'
check "moshi=off sends nothing"                sh -c 'aleph settings set moshi off </dev/null >/dev/null && : > "$ST/log" && aleph moshi sync </dev/null >/dev/null; aleph settings unset moshi </dev/null >/dev/null; ! grep -q "moshi-hook notify\|moshi-hook ask\|moshi-hook job" "$ST/log"'
check "moshi is off by default"                sh -c 'aleph settings unset moshi </dev/null >/dev/null && : > "$ST/log" && aleph moshi sync </dev/null >/dev/null; ! grep -q "moshi-hook notify\|moshi-hook ask\|moshi-hook job" "$ST/log"'
# --- Focus, Tile and new terminal tabs
check "open-tab --dry-run plans a Warp tab"     sh -c 'aleph open-tab --terminal warp --dry-run -- herdr --remote b31 </dev/null | grep -q "warp://tab_config/aleph_tab" && aleph open-tab --terminal warp --dry-run -- herdr --remote b31 </dev/null | grep -q "commands = \[\"herdr --remote b31\"\]"'
check "open-tab: kitty, iTerm2, a shell line"   sh -c 'aleph open-tab --terminal kitty --dry-run -- htop </dev/null | grep -q "kitty @ launch --type=tab" && aleph open-tab --terminal iterm --dry-run -- "cd /tmp && ls" </dev/null | grep -q "write text"'
check "send --after: later waits, idle goes"  sh -c 'aleph queue clear </dev/null >/dev/null; aleph send shell "later please" --after 2h </dev/null >/dev/null && aleph send shell "now please" --after idle </dev/null >/dev/null && aleph queue ls --json </dev/null | jq -e "[.[] | select(.to==\"shell\" and .after != null)] | length == 1" >/dev/null && : > "$ST/log" && { aleph watch --interval 5 </dev/null >/dev/null 2>&1 & p=$!; sleep 7; kill $p; }; grep -q "PROMPT w1:p9 now please" "$ST/log" && ! grep -q "later please" "$ST/log"; r=$?; aleph queue clear </dev/null >/dev/null; exit $r'
check "note: set, tags, list, clear"         sh -c 'aleph note b31:temper "waiting on the #data refresh" </dev/null >/dev/null && aleph note --json </dev/null | jq -e "any(.[]; .name==\"temper\" and .tags==[\"data\"])" >/dev/null && aleph note b31:temper --clear </dev/null >/dev/null && ! aleph note --json </dev/null | jq -e "any(.[]; .name==\"temper\")" >/dev/null'
# --- presets with panes
check "preset import shows the plan, saves with --yes" sh -c 'printf "[presets.ml]\nlayout = \"columns\"\nvars = { repo = \"/srv/hunt\" }\n[[presets.ml.panes]]\nname = \"train\"\nhost = \"b31\"\nagent = \"claude\"\ndir = \"\${repo}\"\n[[presets.ml.panes]]\nname = \"review\"\nhost = \"b31\"\nagent = \"codex\"\ndir = \"\${repo}\"\n" > "$ST/ml.toml" && aleph preset import "$ST/ml.toml" --dry-run </dev/null 2>&1 | grep -q "train" && aleph preset import "$ST/ml.toml" --yes </dev/null >/dev/null && aleph preset ls --json </dev/null | jq -e "any(.[]; .name==\"ml\" and (.panes | length == 2))" >/dev/null && aleph preset validate ml </dev/null >/dev/null'
check "preset launch: a tab, then a split beside it" sh -c ': > "$ST/log"; aleph preset launch ml --detach </dev/null >/dev/null 2>&1; grep -q "tab create.*--cwd /srv/hunt" "$ST/log" && grep -q "pane split .* --direction right" "$ST/log" && [ "$(grep -c "^herdr agent start" "$ST/log")" -ge 2 ]'
check "preset export --generic turns machines into vars" sh -c 'aleph preset export ml --generic </dev/null | grep -q "host1 = \"b31\"" && aleph preset export ml --generic </dev/null | grep -q "host = \"\${host1}\""'
# --- exact layouts over herdr's socket (the fake server: examples/fake_herdr_sock.rs, fakesock.sh; ssh -N -L links to it)
check "socket: the fake herdr listens, herdr status server names it" sh -c '"$ST/../../fakesock.sh" start b31 gpu2 && ssh b31 herdr status server | grep -q "^socket: .*/b31.sock$"'
check "new --tile 3: one layout.apply over a forward, no splits" sh -c ': > "$ST/log"; aleph --host b31 new --agent claude --tile 3 --name trio --detach </dev/null >/dev/null 2>&1 && [ "$(grep -c "^sock b31 layout.apply" "$ST/log")" = 1 ] && grep "^sock b31 layout.apply" "$ST/log" | grep -q "\"tab_label\":\"claude_trio+2\"" && ! grep -q "pane split" "$ST/log" && grep -q "^ssh .* -N -T -L .* b31$" "$ST/log" && [ "$(grep -c "^herdr agent start trio" "$ST/log")" = 3 ] && aleph ls --json </dev/null | jq -e "[.hosts[].sessions[] | select(.name | startswith(\"trio\")) | .tab_id] | length == 3 and (unique | length == 1)" >/dev/null'
check "preset save from one tab keeps its layout (layout.export)" sh -c ': > "$ST/log"; aleph preset save trio b31:trio b31:trio-2 b31:trio-3 </dev/null >/dev/null 2>&1 && grep -q "^sock b31 layout.export" "$ST/log" && aleph preset show trio --json </dev/null | jq -e ".layout == \"herdr\" and .shape == \"((trio / trio-2) | trio-3)\"" >/dev/null && aleph preset export trio </dev/null | grep -q "^tree = { right = 0.5, first = { down = 0.5"'
check "preset launch (layout herdr): the tree in one layout.apply" sh -c ': > "$ST/log"; aleph preset launch trio --detach </dev/null >/dev/null 2>&1 && [ "$(grep -c "^sock b31 layout.apply" "$ST/log")" = 1 ] && grep "^sock b31 layout.apply" "$ST/log" | grep -q "\"root\":{\"direction\":\"right\",\"first\":{\"direction\":\"down\"" && ! grep -q "pane split" "$ST/log" && [ "$(grep -c "^herdr agent start" "$ST/log")" = 3 ]'
check "an older herdr (no layout.apply): the same shape by splits" sh -c 'touch "$ST/sockold_b31"; : > "$ST/log"; aleph preset launch trio --detach </dev/null >/dev/null 2>&1; r=$?; rm -f "$ST/sockold_b31"; [ $r = 0 ] && grep -q "^sock b31 layout.apply" "$ST/log" && grep -q "^herdr tab create" "$ST/log" && grep -q "pane split .* --direction right --ratio 0.500" "$ST/log" && grep -q "pane split .* --direction down --ratio 0.500" "$ST/log" && [ "$(grep -c "^herdr agent start" "$ST/log")" = 3 ]'
check "tile: pane.move over the socket, in a grid's shape" sh -c ': > "$ST/log"; aleph tile trio trio-2 trio-3 </dev/null >/dev/null 2>&1 && [ "$(grep -c "^sock b31 pane.move" "$ST/log")" = 3 ] && grep "^sock b31 pane.move" "$ST/log" | grep -q "\"label\":\"tile:trio+trio-2+trio-3\",\"type\":\"new_tab\"" && grep "^sock b31 pane.move" "$ST/log" | grep -q "\"ratio\":0.5,\"split\":\"down\"" && ! grep -q "^herdr pane move" "$ST/log"'
check "events: the listener subscribes over its forward, hears herdr" sh -c ': > "$ST/log"; aleph events --json </dev/null > "$ST/events.out" 2>&1 & p=$!; i=0; until grep -q "^sock b31 events.subscribe" "$ST/log" || [ $i -ge 100 ]; do sleep 0.1; i=$((i+1)); done; echo "{\"event\":\"pane_agent_status_changed\",\"data\":{\"pane_id\":\"w1:p3\",\"agent_status\":\"blocked\"}}" > "$ST/sockevent_b31"; i=0; until grep -q "w1:p3" "$ST/events.out" || [ $i -ge 50 ]; do sleep 0.1; i=$((i+1)); done; kill $p; wait $p 2>/dev/null; rm -f "$ST/sockevent_b31"; grep -q "\"event\":\"pane.agent_status_changed\"" "$ST/events.out" && grep -q "^ssh .* -N -T -L .*/ev/b31.sock:" "$ST/log"'
check "--via: aleph on the fake machine's PATH, its herdr is local there" sh -c 'touch "$ST/aleph_b31"; had=0; [ -e "$RHOME/.config/aleph" ] && had=1; out=$(aleph --via b31 ls --json </dev/null); r=$?; rm -f "$ST/aleph_b31"; rm -rf "$RHOME/.cache/aleph" "$RHOME/.local/state/aleph"; [ $had = 1 ] || rm -rf "$RHOME/.config/aleph"; [ $r = 0 ] && printf "%s" "$out" | jq -e ".hosts | length == 1 and .[0].alias == \"local\" and (.[0].sessions | length >= 3)" >/dev/null'
# --- OpenRouter: the key in the keystore, in sessions only over herdr's socket, never in any log; its spend
# (the fake world keeps secrets in state/secrets.toml, ALEPH_SECRETS_FILE: every grep for the key leaves that one file out)
export ORK=sk-or-v1-5m0ke5m0ke00fa4e00000000000000000000000000000000000000000000c0de
check "openrouter: secret set stores it; secret ls lists it" sh -c 'aleph secret ls </dev/null | grep -q "openrouter.key .*secret:openrouter .*not set" && printf "%s\n" "$ORK" | aleph secret set openrouter 2>&1 | grep -q "points at it already" && aleph secret ls </dev/null | grep -q "openrouter.key .*secret:openrouter .*stored" && [ "$(aleph settings get openrouter.key </dev/null)" = secret:openrouter ] && ! grep -rqF --exclude=secrets.toml -- "$ORK" "$XDG_STATE_HOME/aleph" "$HOME/.config/aleph"'
check "openrouter: usage --json has the account from its API, the key on curl's stdin" sh -c ': > "$ST/log"; aleph usage --json </dev/null | jq -e ".openrouter.spent.today == 0.4211 and .openrouter.spent.total == 40.1032 and .openrouter.credits.left > 60 and .openrouter.limit == 50 and .openrouter.limit_remaining == 37.25 and (.openrouter.stale | not) and .openrouter.error == null" >/dev/null && grep -q "^OPENROUTER GET /key auth=yes" "$ST/log" && grep -q "^OPENROUTER GET /credits auth=yes" "$ST/log" && ! grep -q -- "$ORK" "$ST/log" && ! grep -rq -- "$ORK" "$XDG_CACHE_HOME/aleph/openrouter"'
check "openrouter: an opencode session gets it in one layout.apply, never on a command line" sh -c ': > "$ST/log"; ALEPH_DEBUG="$ST/or-debug.log" aleph --host b31 new --agent opencode --name orkey --detach --json </dev/null | jq -e ".note == null and .name == \"orkey\"" >/dev/null && [ "$(grep -c "^sock b31 layout.apply" "$ST/log")" = 1 ] && grep "^sock b31 layout.apply" "$ST/log" | grep -qF "\"OPENROUTER_API_KEY\":\"…${#ORK}\"" && grep -q "^herdr agent start orkey --kind opencode" "$ST/log" && ! grep -q "^herdr tab create" "$ST/log" && grep -q "sock b31 layout.apply" "$ST/or-debug.log" && ! grep -rqF --exclude=secrets.toml -- "$ORK" "$ST/log" "$ST/or-debug.log" "$XDG_STATE_HOME/aleph" "$XDG_CACHE_HOME/aleph/openrouter" "$ST"/layout_b31_*'
check "openrouter: an agent not in openrouter.agents never gets it" sh -c ': > "$ST/log"; aleph --host b31 new --agent claude --name nokey --detach </dev/null >/dev/null 2>&1 && grep -q "^herdr tab create --label claude_nokey" "$ST/log" && ! grep -q "OPENROUTER" "$ST/log"'
check "openrouter: --openrouter starts the agent on that model its own way" sh -c ': > "$ST/log"; aleph --host b31 new --agent opencode --openrouter qwen/qwen3-coder --name ormodel --detach </dev/null >/dev/null 2>&1 && grep -q "^herdr agent start ormodel --kind opencode .* -- --model openrouter/qwen/qwen3-coder$" "$ST/log" && ! aleph --host b31 new --agent claude --openrouter qwen/qwen3-coder --detach </dev/null 2>/dev/null && ! grep -qF -- "$ORK" "$ST/log"'
check "openrouter: a refused key says so; a dead link keeps the last numbers, marked stale" sh -c 'S="$XDG_CACHE_HOME/aleph/openrouter/spend.json"; jq ".at -= 1200" "$S" > "$S.t" && mv "$S.t" "$S" && touch "$ST/openrouter_down" && o=$(aleph usage --json </dev/null); rm -f "$ST/openrouter_down"; printf "%s" "$o" | jq -e ".openrouter.stale and .openrouter.spent.total == 40.1032 and (.openrouter.error | test(\"reach OpenRouter\"))" >/dev/null && printf "sk-or-v1-bad\n" | aleph secret set openrouter >/dev/null 2>&1 && rm -f "$S" && aleph usage --json </dev/null | jq -e ".openrouter.error | test(\"refused the key\")" >/dev/null; r=$?; printf "%s\n" "$ORK" | aleph secret set openrouter >/dev/null 2>&1; exit $r'
check "socket gone: herdr stops naming it, Aleph splits again" sh -c '"$ST/../../fakesock.sh" stop && ! ssh b31 herdr status server | grep -q "^socket:" && : > "$ST/log" && aleph --host b31 new --tile 2 --name duo --detach </dev/null >/dev/null 2>&1 && ! grep -q "^sock " "$ST/log" && grep -q "pane split .* --direction right --ratio 0.500" "$ST/log"'
check "no socket: tile moves with herdr's CLI, ratios too" sh -c ': > "$ST/log"; aleph tile duo duo-2 </dev/null >/dev/null 2>&1 && grep -q "^herdr pane move .* --new-tab --label tile:duo+duo-2" "$ST/log" && grep -q "^herdr pane move .* --split right --target-pane .* --ratio 0.500" "$ST/log"'
check "openrouter, no socket: the key stays out and the start says why (and the Inbox)" sh -c ': > "$ST/log"; o=$(aleph --host b31 new --agent opencode --name orcli --detach </dev/null 2>&1); printf "%s" "$o" | grep -q "OPENROUTER_API_KEY isn.t in this session: herdr.s socket on b31 isn.t reachable" && grep -q "^herdr tab create --label opencode_orcli" "$ST/log" && ! grep -q "^sock " "$ST/log" && ! grep -rqF --exclude=secrets.toml -- "$ORK" "$ST/log" "$XDG_STATE_HOME/aleph" && aleph inbox --json </dev/null | jq -e "any(.[]; .kind == \"error\" and .name == \"orcli\" and (.title | test(\"OPENROUTER_API_KEY\")))" >/dev/null; r=$?; aleph secret rm openrouter </dev/null >/dev/null 2>&1; exit $r'
# --- the notification router
check "router: a new question reaches ntfy from the daemon" sh -c 'aleph settings set notify.ntfy https://ntfy.sh/route-smoke </dev/null >/dev/null; aleph settings set notify.question_after 0 </dev/null >/dev/null; A="$ST/agents_b31.json"; cp "$A" "$A.r"; : > "$ST/log"; aleph watch --interval 5 </dev/null >/dev/null 2>&1 & p=$!; sleep 3; jq "(.result.agents[] | select(.pane_id==\"w1:p3\")).agent_status = \"blocked\"" "$A.r" > "$A"; sleep 7; kill $p; cp "$A.r" "$A"; aleph settings unset notify.ntfy </dev/null >/dev/null; aleph settings unset notify.question_after </dev/null >/dev/null; grep -qE "topic.{1,6}route-smoke" "$ST/log" && grep -q "needs you" "$ST/log" && grep -q "Claude Code · b31" "$ST/log"'
check "router: a question answered within the grace never reaches the phone" sh -c 'aleph settings set notify.ntfy https://ntfy.sh/route-smoke </dev/null >/dev/null; aleph settings set notify.question_after 12s </dev/null >/dev/null; A="$ST/agents_b31.json"; cp "$A" "$A.r"; : > "$ST/log"; aleph watch --interval 5 </dev/null >/dev/null 2>&1 & p=$!; sleep 3; jq "(.result.agents[] | select(.pane_id==\"w1:p3\")).agent_status = \"blocked\"" "$A.r" > "$A"; sleep 5; cp "$A.r" "$A"; sleep 14; kill $p; cp "$A.r" "$A"; aleph settings unset notify.ntfy </dev/null >/dev/null; aleph settings unset notify.question_after </dev/null >/dev/null; ! grep -qE "topic.{1,6}route-smoke" "$ST/log"'
check "router: a question still waiting after the grace does" sh -c 'aleph settings set notify.ntfy https://ntfy.sh/route-smoke </dev/null >/dev/null; aleph settings set notify.question_after 3s </dev/null >/dev/null; A="$ST/agents_b31.json"; cp "$A" "$A.r"; : > "$ST/log"; aleph watch --interval 5 </dev/null >/dev/null 2>&1 & p=$!; sleep 3; jq "(.result.agents[] | select(.pane_id==\"w1:p9\")).agent_status = \"blocked\"" "$A.r" > "$A"; sleep 20; kill $p; cp "$A.r" "$A"; aleph settings unset notify.ntfy </dev/null >/dev/null; aleph settings unset notify.question_after </dev/null >/dev/null; grep -qE "topic.{1,6}route-smoke" "$ST/log" && grep -q "needs you" "$ST/log"'
check "router: do not disturb holds it" sh -c 'aleph settings set notify.ntfy https://ntfy.sh/route-smoke </dev/null >/dev/null; aleph notify dnd 1h </dev/null >/dev/null; A="$ST/agents_b31.json"; cp "$A" "$A.r"; : > "$ST/log"; aleph watch --interval 5 </dev/null >/dev/null 2>&1 & p=$!; sleep 3; jq "(.result.agents[] | select(.pane_id==\"w1:p3\")).agent_status = \"blocked\"" "$A.r" > "$A"; sleep 7; kill $p; cp "$A.r" "$A"; aleph notify dnd off </dev/null >/dev/null; aleph settings unset notify.ntfy </dev/null >/dev/null; ! grep -q "ntfy.sh/route-smoke" "$ST/log"'
check "router: a finished turn's alert says what it took (its machine's usage read first)" sh -c 'aleph settings set notify.ntfy https://ntfy.sh/turn-smoke </dev/null >/dev/null; aleph settings set notify.done_min 0 </dev/null >/dev/null; aleph usage --host b31 --json </dev/null >/dev/null 2>&1; A="$ST/agents_b31.json"; cp "$A" "$A.t"; L=$(ls "$RHOME"/.claude/projects/*/3f2a9c1e-0b7d-4c55-9a61-2e8f0c4d7a10.jsonl | head -n 1); : > "$ST/log"; aleph watch --interval 5 </dev/null >/dev/null 2>&1 & p=$!; sleep 4; ts=$(date -u +%Y-%m-%dT%H:%M:%S.000Z); printf "%s\n" "{\"isSidechain\":false,\"message\":{\"model\":\"claude-opus-5-5\",\"id\":\"msg_TURN_SMOKE\",\"role\":\"assistant\",\"usage\":{\"input_tokens\":400000,\"cache_creation_input_tokens\":0,\"cache_read_input_tokens\":0,\"output_tokens\":12000}},\"requestId\":\"req_turn_smoke\",\"type\":\"assistant\",\"timestamp\":\"$ts\",\"sessionId\":\"3f2a9c1e-0b7d-4c55-9a61-2e8f0c4d7a10\"}" >> "$L"; sleep 1; jq "(.result.agents[] | select(.pane_id==\"w1:p3\")).agent_status = \"idle\"" "$A.t" > "$A"; sleep 15; kill $p; cp "$A.t" "$A"; aleph settings unset notify.ntfy </dev/null >/dev/null; aleph settings unset notify.done_min </dev/null >/dev/null; grep -q "finished its turn" "$ST/log" && grep -q "this turn: 412k tok" "$ST/log"'
check "notify routes lists where events go"      sh -c 'aleph settings set notify.ntfy https://ntfy.sh/x </dev/null >/dev/null; aleph notify routes --json </dev/null | jq -e "any(.[]; .to == [\"ntfy\"])" >/dev/null; r=$?; aleph settings unset notify.ntfy </dev/null >/dev/null; exit $r'
# --- agent hooks (opt-in): the agents' own words, through a spool on each machine
check "hooks: OpenCode gets a plugin of ours (no plugins folder yet), removed whole" sh -c 'rm -rf "$RHOME/.config/opencode"; mkdir -p "$RHOME/.config/opencode" && aleph --host b31 hooks install --agent opencode --yes </dev/null >/dev/null && grep -q "aleph-hook" "$RHOME/.config/opencode/plugins/aleph-hook.js" && aleph --host b31 hooks status </dev/null | grep -q "opencode installed" && aleph --host b31 hooks remove --agent opencode --yes </dev/null >/dev/null && [ ! -e "$RHOME/.config/opencode/plugins/aleph-hook.js" ]'
check "hooks install: beside herdr's, with a backup; remove: back as it was" sh -c 'mkdir -p "$RHOME/.claude" && printf "{\n  \"hooks\": {\n    \"SessionStart\": [\n      {\n        \"matcher\": \"*\",\n        \"hooks\": [\n          {\n            \"type\": \"command\",\n            \"command\": \"herdr-agent-state.sh\"\n          }\n        ]\n      }\n    ]\n  }\n}\n" > "$RHOME/.claude/settings.json" && cp "$RHOME/.claude/settings.json" "$ST/settings.orig" && aleph --host b31 hooks install --agent claude --yes </dev/null >/dev/null && grep -q "aleph-hook" "$RHOME/.claude/settings.json" && grep -q "herdr-agent-state" "$RHOME/.claude/settings.json" && ls "$RHOME"/.claude/settings.json.aleph-bak-* >/dev/null 2>&1 && aleph --host b31 hooks status </dev/null | grep -q "claude   installed" && aleph --host b31 hooks remove --agent claude --yes </dev/null >/dev/null && cmp -s "$RHOME/.claude/settings.json" "$ST/settings.orig"'
check "spool: an agent's own words reach the inbox" sh -c 'aleph settings set host.b31.hooks on </dev/null >/dev/null; rm -f "$RHOME/.local/state/aleph/spool.jsonl"; aleph watch --interval 5 </dev/null >/dev/null 2>&1 & p=$!; sleep 6; mkdir -p "$RHOME/.local/state/aleph"; printf "{\"t\":%s,\"agent\":\"claude\",\"pane\":\"w1:p2\",\"hook\":{\"hook_event_name\":\"Notification\",\"message\":\"Claude needs your permission to use Bash\"}}\n" "$(date +%s)" >> "$RHOME/.local/state/aleph/spool.jsonl"; sleep 9; kill $p; aleph inbox -n 20 --json </dev/null | jq -e "any(.[]; .source == \"agent\" and (.title | test(\"permission to use Bash\")) and .name == \"temper\")" >/dev/null'
# --- two-way: a phone button (ntfy reply topic) answers a question
check "phone button: approve sends the yes option, once, and it's audited" sh -c 'aleph settings set moshi off </dev/null >/dev/null; aleph settings set notify.ntfy https://ntfy.sh/btn-smoke </dev/null >/dev/null; aleph settings set remote.allow "b31:*" </dev/null >/dev/null; tok=$(aleph notify token b31:temper approve </dev/null) && printf "{\"id\":\"m1\",\"event\":\"message\",\"message\":\"%s\"}\n{\"id\":\"m2\",\"event\":\"message\",\"message\":\"%s\"}\n" "$tok" "$tok" > "$ST/ntfy_replies"; : > "$ST/log"; aleph watch --interval 5 </dev/null >/dev/null 2>&1 & p=$!; sleep 8; kill $p; aleph settings unset remote.allow </dev/null >/dev/null; aleph settings unset notify.ntfy </dev/null >/dev/null; aleph settings unset moshi </dev/null >/dev/null; [ "$(grep -c "^herdr agent send-keys w1:p2 1" "$ST/log")" -eq 1 ] && grep -q "already used" "$ST/log" && aleph inbox -n 20 --json </dev/null | jq -e "any(.[]; .kind == \"remote\" and (.title | test(\"approved from the phone\")))" >/dev/null'
check "phone button: refused without remote control" sh -c 'aleph settings set moshi off </dev/null >/dev/null; aleph settings set notify.ntfy https://ntfy.sh/btn-smoke </dev/null >/dev/null; aleph settings set remote.allow "b31:*" </dev/null >/dev/null; tok=$(aleph notify token b31:temper approve </dev/null); aleph settings set remote.allow "gpu2:*" </dev/null >/dev/null; printf "{\"id\":\"m3\",\"event\":\"message\",\"message\":\"%s\"}\n" "$tok" > "$ST/ntfy_replies"; : > "$ST/log"; aleph watch --interval 5 </dev/null >/dev/null 2>&1 & p=$!; sleep 8; kill $p; aleph settings unset remote.allow </dev/null >/dev/null; aleph settings unset notify.ntfy </dev/null >/dev/null; aleph settings unset moshi </dev/null >/dev/null; ! grep -q "agent send-keys w1:p2" "$ST/log" && grep -q "remote control isn" "$ST/log"'
check "test alert: its buttons come back, are recorded, touch nothing" sh -c 'aleph settings set moshi off </dev/null >/dev/null; aleph settings set notify.ntfy https://ntfy.sh/btn-smoke </dev/null >/dev/null; : > "$ST/log"; aleph --host b31 notify test --agent claude --to ntfy </dev/null >/dev/null 2>&1; tok=$(grep -o "v1\.b31\.test:claude\.[0-9]*\.approve\.[0-9a-f.]*" "$ST/log" | head -1); [ -n "$tok" ] && grep -q "Test · [a-z_-]* needs you" "$ST/log" && printf "{\"id\":\"t1\",\"event\":\"message\",\"message\":\"%s\"}\n" "$tok" > "$ST/ntfy_replies"; : > "$ST/log"; aleph watch --interval 5 </dev/null >/dev/null 2>&1 & p=$!; sleep 8; kill $p; aleph settings unset notify.ntfy </dev/null >/dev/null; aleph settings unset moshi </dev/null >/dev/null; [ -n "$tok" ] && ! grep -q "send-keys" "$ST/log" && grep -q "reached Aleph" "$ST/log" && aleph inbox -n 20 --json </dev/null | jq -e "any(.[]; .kind == \"remote\" and (.title | test(\"test: Yes from .* reached Aleph\")))" >/dev/null'
check "wait, send --wait, reply by event id"   sh -c ': > "$ST/log"; aleph wait gpu2:weave --until idle --timeout 5s --json </dev/null | jq -e ".state == \"done\"" >/dev/null && grep -q "agent wait w1:p4 --until idle --timeout 5000" "$ST/log" && aleph send gpu2:weave "go on" --wait </dev/null >/dev/null 2>&1 && grep -q "agent prompt w1:p4 go on --wait" "$ST/log" && id=$(aleph inbox -n 50 --json </dev/null | jq -r "[.[] | select(.name == \"weave\")][0].id // empty"); [ -z "$id" ] || { aleph reply "$id" "thanks" </dev/null >/dev/null && grep -q "PROMPT w1:p4 thanks" "$ST/log"; }'
# --- the daemon's API (state/daemon.sock; binding it is the one-daemon lock)
check "api: the daemon answers on its socket" sh -c 'aleph daemon status </dev/null >/dev/null 2>&1 && exit 1; aleph watch --interval 5 </dev/null >/dev/null 2>&1 & p=$!; i=0; until aleph api daemon.ping </dev/null >/dev/null 2>&1 || [ $i -ge 40 ]; do sleep 0.25; i=$((i+1)); done; sleep 1; : > "$ST/log"; aleph api state.snapshot </dev/null | jq -e "(.hosts | length) == 2" >/dev/null && aleph api session.list "{\"host\":\"b31\"}" </dev/null | jq -e "any(.[]; .name == \"temper\")" >/dev/null && aleph api session.keys "{\"session\":\"b31:temper\",\"keys\":[\"2\"]}" </dev/null >/dev/null && grep -q "agent send-keys w1:p2 2" "$ST/log" && aleph daemon status --json </dev/null | jq -e ".running and .hub" >/dev/null && printf "{\"id\":1,\"method\":\"events.subscribe\"}\n" | aleph api --stdio | head -n 2 | jq -se ".[0].result.subscribed and (.[1].state.hosts | length) == 2" >/dev/null && ! aleph api config.set "{}" </dev/null 2>/dev/null; r=$?; kill $p; exit $r'
check "api: one daemon per computer" sh -c 'aleph watch --interval 5 </dev/null >/dev/null 2>&1 & p=$!; i=0; until aleph api daemon.ping </dev/null >/dev/null 2>&1 || [ $i -ge 40 ]; do sleep 0.25; i=$((i+1)); done; aleph watch --interval 5 </dev/null >/dev/null 2>&1 & q=$!; sleep 2; pid=$(aleph api daemon.ping </dev/null | jq -r .pid); kill $p; sleep 6; pid2=$(aleph api daemon.ping </dev/null 2>/dev/null | jq -r .pid); kill $q; [ "$pid" = "$p" ] && [ "$pid2" = "$q" ]'
check "api: the daemon keeps agents, servers, doctor, usage; topics push" sh -c 'aleph watch --interval 5 </dev/null >/dev/null 2>&1 & p=$!; i=0; until aleph api daemon.ping </dev/null >/dev/null 2>&1 || [ $i -ge 40 ]; do sleep 0.25; i=$((i+1)); done; r=0; aleph api agents.list </dev/null | jq -e "(.hosts | length) == 2 and all(.hosts[]; .reachable)" >/dev/null || r=1; aleph api services.list "{\"host\":\"b31\"}" </dev/null | jq -e ".hosts[0].alias == \"b31\"" >/dev/null || r=2; aleph api doctor.get </dev/null | jq -e "has(\"running\") and has(\"sections\")" >/dev/null || r=3; aleph api usage.now </dev/null | jq -e "has(\"total\") and (.machines | length) == 2" >/dev/null || r=4; aleph api config.list </dev/null | jq -e "has(\"hosts\")" >/dev/null || r=5; aleph api screen.read "{\"session\":\"b31:temper\",\"ansi\":true}" </dev/null | jq -e ".name == \"temper\" and has(\"approve_keys\")" >/dev/null || r=6; ( sleep 1.5; aleph note b31:temper "subscribed test" </dev/null >/dev/null 2>&1 ) & printf "{\"id\":1,\"method\":\"events.subscribe\",\"params\":{\"state\":false,\"topics\":[\"notes\"]}}\n" | aleph api --stdio | head -n 2 | jq -se ".[1].changed == \"notes\"" >/dev/null || r=7; aleph note b31:temper --clear </dev/null >/dev/null 2>&1; kill $p; [ $r -eq 0 ] || { echo "step $r"; exit 1; }'
check "api: stream.open sends a session's screen" sh -c 'aleph watch --interval 5 </dev/null >/dev/null 2>&1 & p=$!; i=0; until aleph api daemon.ping </dev/null >/dev/null 2>&1 || [ $i -ge 40 ]; do sleep 0.25; i=$((i+1)); done; printf "{\"id\":1,\"method\":\"stream.open\",\"params\":{\"session\":\"b31:temper\"}}\n" | aleph api --stdio | head -n 2 | jq -se ".[0].result.streaming and ((.[1].screen // \"\") | length > 0)" >/dev/null; r=$?; kill $p; exit $r'
# --- watch rules (herdr matches; here: the settings and the CLI)
check "notify watch: add, list, remove" sh -c 'aleph notify watch add tests "FAILED|Traceback" --regex --host b31 </dev/null >/dev/null && aleph notify watch ls --json </dev/null | jq -e ".[0].name == \"tests\" and .[0].regex and .[0].hosts == [\"b31\"]" >/dev/null && aleph config check </dev/null >/dev/null 2>&1 && aleph notify watch rm tests </dev/null >/dev/null && aleph notify watch ls --json </dev/null | jq -e "length == 0" >/dev/null'
# --- faults: hung, slow and flapping machines; corrupt or unwritable state
check "a hung machine never holds the others up" sh -c 'echo timeout > "$ST/mode_gpu2"; t0=$(date +%s); o=$(aleph ls --json </dev/null 2>/dev/null); t=$(( $(date +%s) - t0 )); rm -f "$ST/mode_gpu2"; [ $t -lt 30 ] && printf "%s" "$o" | jq -e "[.hosts[] | select(.alias==\"b31\") | .sessions[]] | length >= 1" >/dev/null'
check "a slow machine still answers" sh -c 'echo slow > "$ST/mode_b31"; o=$(aleph ls --json </dev/null 2>/dev/null); rm -f "$ST/mode_b31"; printf "%s" "$o" | jq -e "[.hosts[] | select(.alias==\"b31\") | .reachable] == [true]" >/dev/null'
check "a flapping machine comes back on the next try" sh -c 'echo flap > "$ST/mode_gpu2"; rm -f "$ST/flap_gpu2"; aleph ls --json </dev/null >/dev/null 2>&1; o=$(aleph ls --json </dev/null 2>/dev/null); rm -f "$ST/mode_gpu2" "$ST/flap_gpu2"; printf "%s" "$o" | jq -e ".hosts | length == 2" >/dev/null'
check "corrupt state files never crash a command" sh -c 'C="$XDG_CACHE_HOME/aleph"; S="$XDG_STATE_HOME/aleph"; mkdir -p "$C" "$S"; for f in "$C/fleet.json" "$S/events.jsonl" "$S/queue.json" "$S/sessions.json" "$S/inbox_dismissed" "$S/notify_mute.json"; do [ -f "$f" ] && cp "$f" "$f.keep"; printf "{not json\n\0garbage" > "$f"; done; r=0; for c in "ls --json" "inbox --json" "queue ls" "restore --dry-run" "notify routes" "usage --json" "status --json"; do o=$(aleph $c </dev/null 2>&1); printf "%s" "$o" | grep -qi "panicked" && { echo "$c: $o"; r=1; }; done; for f in "$C/fleet.json" "$S/events.jsonl" "$S/queue.json" "$S/sessions.json" "$S/inbox_dismissed" "$S/notify_mute.json"; do if [ -f "$f.keep" ]; then mv "$f.keep" "$f"; else rm -f "$f"; fi; done; exit $r'
check "an unwritable state folder is survivable" sh -c 'S="$XDG_STATE_HOME/aleph"; chmod 500 "$S"; o=$(aleph ls --json </dev/null 2>&1); r=$?; chmod 700 "$S"; [ $r -eq 0 ] && ! printf "%s" "$o" | grep -qi panicked'
# --- Wake-on-LAN (the fake wakeonlan records the MAC; nothing is sent)
check "wake: a magic packet with the machine's MAC" sh -c 'aleph settings set host.b31.mac AA-BB-CC-DD-EE-01 </dev/null >/dev/null; : > "$ST/log"; aleph wake b31 </dev/null >/dev/null 2>&1; r=$?; aleph settings unset host.b31.mac </dev/null >/dev/null; [ $r -eq 0 ] && grep -q "wakeonlan aa:bb:cc:dd:ee:01" "$ST/log"'
check "wake: says when it doesn't know the MAC" sh -c '! aleph wake nowhere </dev/null >/dev/null 2>"$ST/wake.err" && grep -q "no MAC address known" "$ST/wake.err"'
# --- clone / move a session to another machine
check "clone: the same agent on another machine; a missing folder is asked for" sh -c 'touch "$ST/up_gpu2"; rm -f "$ST/mode_gpu2"; cp "$ST/agents_b31.json" "$ST/agents_b31.cl"; cp "$ST/agents_gpu2.json" "$ST/agents_gpu2.cl"; ! aleph clone b31:temper --to gpu2 </dev/null >/dev/null 2>"$ST/cl.err" && grep -q "name a folder there" "$ST/cl.err" && : > "$ST/log" && aleph clone b31:temper --to gpu2 --dir "$RHOME" </dev/null >/dev/null 2>&1 && grep -q "agent start .* --kind claude" "$ST/log" && ! grep -q "pane close w1:p2" "$ST/log" && aleph clone b31:temper --to gpu2 --dir "$RHOME" --move --yes </dev/null >/dev/null 2>&1 && grep -q "pane close w1:p2" "$ST/log"; r=$?; cp "$ST/agents_b31.cl" "$ST/agents_b31.json"; cp "$ST/agents_gpu2.cl" "$ST/agents_gpu2.json"; exit $r'
# --- the HTTP API (api.http): tokens, scopes, remote.allow, CSRF, Host, metrics, SSE, the console
check "http: tokens and scopes, remote.allow, CSRF, Host allowlist, metrics, SSE, console" sh -c 'C=/usr/bin/curl; U=http://127.0.0.1:17878; aleph settings set api.http on </dev/null >/dev/null; aleph settings set api.listen 127.0.0.1:17878 </dev/null >/dev/null; aleph watch --interval 5 </dev/null >/dev/null 2>&1 & p=$!; for i in $(seq 1 40); do $C -s -o /dev/null $U/ && break; sleep 0.25; done; R=$(aleph daemon token new tab --scope read </dev/null 2>/dev/null | grep -oE "[A-Za-z0-9_-]{30,}" | head -1); W=$(aleph daemon token new ph --scope reply </dev/null 2>/dev/null | grep -oE "[A-Za-z0-9_-]{30,}" | head -1); r=0; [ "$($C -s -o /dev/null -w %{http_code} $U/api/v1/state.snapshot)" = 401 ] || { [ $r -eq 0 ] \&\& r=1; }; [ "$($C -s -o /dev/null -w %{http_code} -H "Authorization: Bearer $R" $U/api/v1/state.snapshot)" = 200 ] || { [ $r -eq 0 ] \&\& r=2; }; [ "$($C -s -o /dev/null -w %{http_code} -X POST -H "X-Aleph: 1" -H "Authorization: Bearer $R" -d "{}" $U/api/v1/session.send)" = 403 ] || { [ $r -eq 0 ] \&\& r=3; }; $C -s -X POST -H "X-Aleph: 1" -H "Authorization: Bearer $W" -d "{\"session\":\"b31:temper\",\"text\":\"hi\"}" $U/api/v1/session.send | grep -q "remote control isn" || { [ $r -eq 0 ] \&\& r=4; }; aleph settings set remote.allow "b31:*" </dev/null >/dev/null; : > "$ST/log"; $C -s -X POST -H "X-Aleph: 1" -H "Authorization: Bearer $W" -d "{\"session\":\"b31:ignite\",\"text\":\"from web\"}" $U/api/v1/session.send | grep -q "\"sent\":true" || { [ $r -eq 0 ] \&\& r=5; }; grep -q "w1:p3 from web" "$ST/log" || { [ $r -eq 0 ] \&\& r=6; }; [ "$($C -s -o /dev/null -w %{http_code} -X POST -H "Authorization: Bearer $W" -d "{}" $U/api/v1/inbox.read)" = 403 ] || { [ $r -eq 0 ] \&\& r=7; }; [ "$($C -s -o /dev/null -w %{http_code} -H "Host: evil.example" -H "Authorization: Bearer $R" $U/api/v1/daemon.ping)" = 421 ] || { [ $r -eq 0 ] \&\& r=8; }; $C -s -H "Authorization: Bearer $R" $U/metrics | grep -q "^aleph_" || { [ $r -eq 0 ] \&\& r=9; }; $C -s -m 3 -H "Authorization: Bearer $R" $U/api/v1/events | grep -q "^data:" || { [ $r -eq 0 ] \&\& r=10; }; $C -s $U/ | grep -q "<title>Aleph" || { [ $r -eq 0 ] \&\& r=11; }; aleph inbox -n 300 --json </dev/null | jq -e "any(.[]; .kind == \"remote\" and (.title | test(\"from web\")))" >/dev/null || { [ $r -eq 0 ] \&\& r=12; }; kill $p; aleph settings unset remote.allow </dev/null >/dev/null; aleph settings unset api.http </dev/null >/dev/null; aleph settings unset api.listen </dev/null >/dev/null; [ $r -eq 0 ] || { echo "step $r"; exit 1; }'
# --- aleph connect / --via: Aleph on another machine
check "--via: says when Aleph isn't installed there" sh -c 'rm -f "$RHOME/.local/bin/aleph"; ! aleph --via b31 version </dev/null >/dev/null 2>"$ST/via.err" && grep -q "isn.t installed on b31" "$ST/via.err"'
check "--via runs it there (login PATH, ssh -t)" sh -c 'had=0; [ -e "$RHOME/.config/aleph" ] && had=1; mkdir -p "$RHOME/.local/bin" && ln -sf "$(command -v aleph)" "$RHOME/.local/bin/aleph" && : > "$ST/log" && aleph --via b31 version </dev/null | grep -q "aleph 2" && grep -q "^ssh -t .* b31 sh -lc" "$ST/log"; r=$?; rm -f "$RHOME/.local/bin/aleph"; [ $had = 1 ] || rm -rf "$RHOME/.config/aleph"; exit $r'
check "focus needs a terminal"                  sh -c '! aleph focus ignite </dev/null 2>/dev/null && aleph focus ignite </dev/null 2>&1 | grep -q "needs a terminal"'
# --- the daemon as a service (fake launchctl / systemctl / loginctl; ALEPH_INIT picks one)
check "daemon install --dry-run: the plist and the commands, nothing run" sh -c ': > "$ST/log"; o=$(ALEPH_INIT=launchd aleph daemon install --dry-run </dev/null 2>&1) && printf "%s" "$o" | grep -q "<string>daemon</string>" && printf "%s" "$o" | grep -q "launchctl bootstrap gui/" && ! grep -Eq "^(launchctl|systemctl)" "$ST/log" && [ ! -e "$HOME/Library/LaunchAgents/dev.aleph.daemon.plist" ]'
check "daemon install / restart / stop / start / uninstall (launchd)" sh -c 'export ALEPH_INIT=launchd; : > "$ST/log"; P="$HOME/Library/LaunchAgents/dev.aleph.daemon.plist"; aleph daemon install </dev/null >/dev/null 2>&1 && grep -q "<key>KeepAlive</key>" "$P" && grep -q "^launchctl bootstrap gui/[0-9]* .*dev.aleph.daemon.plist" "$ST/log" && aleph daemon status --json </dev/null | jq -e ".service.installed and .service.loaded and .service.program[1] == \"daemon\"" >/dev/null; [ $? -eq 0 ] || exit 1; aleph daemon restart </dev/null >/dev/null 2>&1 && grep -q "^launchctl kickstart -k gui/[0-9]*/dev.aleph.daemon" "$ST/log" && aleph daemon stop </dev/null >/dev/null 2>&1 && grep -q "^launchctl bootout gui/[0-9]*/dev.aleph.daemon" "$ST/log" && aleph daemon status --json </dev/null | jq -e ".service.loaded | not" >/dev/null && aleph daemon start </dev/null >/dev/null 2>&1 && aleph daemon status --json </dev/null | jq -e ".service.loaded" >/dev/null && aleph daemon uninstall </dev/null >/dev/null 2>&1 && [ ! -e "$P" ] && ! aleph daemon start </dev/null >/dev/null 2>&1'
check "watch --install is daemon install"       sh -c 'export ALEPH_INIT=launchd; : > "$ST/log"; aleph watch --install </dev/null >/dev/null 2>&1 && grep -q "<string>run</string>" "$HOME/Library/LaunchAgents/dev.aleph.daemon.plist" && aleph watch --uninstall </dev/null >/dev/null 2>&1 && [ ! -e "$HOME/Library/LaunchAgents/dev.aleph.daemon.plist" ] && [ "$(grep -c "^launchctl bootstrap" "$ST/log")" = 1 ]'
check "daemon via systemd: the unit, linger said, never changed" sh -c 'export ALEPH_INIT=systemd; : > "$ST/log"; U="$HOME/.config/systemd/user/aleph.service"; o=$(aleph daemon install </dev/null 2>&1) && grep -q "^Restart=on-failure" "$U" && grep -q " daemon run$" "$U" && grep -q "^systemctl --user enable aleph.service" "$ST/log" && grep -q "^systemctl --user restart aleph.service" "$ST/log" && printf "%s" "$o" | grep -q "loginctl enable-linger" && aleph daemon status --json </dev/null | jq -e ".service.running and .service.linger == false" >/dev/null && aleph daemon stop </dev/null >/dev/null 2>&1 && grep -q "^systemctl --user stop aleph.service" "$ST/log" && aleph daemon uninstall </dev/null >/dev/null 2>&1 && [ ! -e "$U" ] && grep -q "^systemctl --user disable --now aleph.service" "$ST/log" && ! grep -q "enable-linger" "$ST/log"'
check "daemon doctor: what the service runs, and that nothing answers" sh -c 'export ALEPH_INIT=launchd; aleph daemon install </dev/null >/dev/null 2>&1; j=$(aleph daemon doctor --json </dev/null); aleph daemon uninstall </dev/null >/dev/null 2>&1; printf "%s" "$j" | jq -e "([.checks[] | select(.label==\"program\" or .label==\"restart\" or .label==\"environment\")] | all(.status == \"ok\")) and ([.checks[] | select(.label==\"socket\")][0].status == \"fail\")" >/dev/null && aleph doctor --json </dev/null | jq -e "[.sections[].section] | index(\"Daemon\") != null" >/dev/null'
# --- exposing the API (fake tailscale / cloudflared: nothing leaves this computer)
check "expose tailscale --dry-run: the serve call, nothing run" sh -c ': > "$ST/log"; aleph daemon expose tailscale --dry-run </dev/null 2>/dev/null | grep -q "tailscale serve --bg --https=443 http://127.0.0.1:7878" && grep -q "^tailscale status --json" "$ST/log" && ! grep -q "^tailscale serve --bg" "$ST/log" && [ -z "$(aleph settings get api.hosts </dev/null)" ]'
check "expose asks first (no tty, no --yes)"   sh -c ': > "$ST/log"; ! aleph daemon expose tailscale </dev/null >/dev/null 2>&1 && ! grep -q "^tailscale serve --bg" "$ST/log"'
check "expose tailscale: an old tailscale is refused" sh -c ': > "$ST/log"; o=$(TS_VERSION=1.50.0 aleph daemon expose tailscale --yes </dev/null 2>&1); [ $? -ne 0 ] && printf "%s" "$o" | grep -q "older than 1.52" && ! grep -q "^tailscale serve --bg" "$ST/log"'
check "expose tailscale --yes: serve, api.hosts, api.http, status" sh -c ': > "$ST/log"; aleph daemon expose tailscale --yes </dev/null >/dev/null 2>&1 && grep -q "^tailscale serve --bg --https=443 http://127.0.0.1:7878$" "$ST/log" && [ "$(aleph settings get api.hosts </dev/null)" = mbp.tail1234.ts.net ] && [ "$(aleph settings get api.http </dev/null)" = on ] && grep -q "^\[api\]" "$HOME/.config/aleph/aleph.toml" && aleph daemon status --json </dev/null | jq -e ".exposure.tailscale[0].url == \"https://mbp.tail1234.ts.net\" and .api.http" >/dev/null && aleph daemon expose tailscale --yes </dev/null 2>&1 | grep -q "already exposed"'
check "expose off: only our entry, never serve reset" sh -c 'S="$ST/ts_serve.json"; jq ".Web[\"mbp.tail1234.ts.net:443\"].Handlers[\"/grafana\"] = {\"Proxy\": \"http://127.0.0.1:3000\"}" "$S" > "$S.n" && mv "$S.n" "$S"; : > "$ST/log"; aleph daemon expose off --yes </dev/null >/dev/null 2>&1 && grep -q "^tailscale serve --https=443 off$" "$ST/log" && ! grep -q "serve reset" "$ST/log" && jq -e ".Web[\"mbp.tail1234.ts.net:443\"].Handlers | has(\"/grafana\") and (has(\"/\") | not)" "$S" >/dev/null && [ -z "$(aleph settings get api.hosts </dev/null)" ]; r=$?; echo "{}" > "$S"; exit $r'
check "expose cloudflare --quick is refused"    sh -c ': > "$ST/log"; o=$(aleph daemon expose cloudflare --quick </dev/null 2>&1); [ $? -ne 0 ] && printf "%s" "$o" | grep -q "trycloudflare" && ! grep -q "^cloudflared" "$ST/log"'
check "expose cloudflare: tunnel, DNS, config, our own unit; Access reminded" sh -c 'export ALEPH_INIT=launchd; mkdir -p "$HOME/.cloudflared" && touch "$HOME/.cloudflared/cert.pem"; : > "$ST/log"; o=$(aleph daemon expose cloudflare --hostname aleph.example.com --yes </dev/null 2>&1) && grep -q "^cloudflared tunnel create aleph$" "$ST/log" && grep -q "^cloudflared tunnel route dns aleph aleph.example.com$" "$ST/log" && grep -q "^launchctl bootstrap gui/[0-9]* .*dev.aleph.cloudflared.plist" "$ST/log" && ! grep -q "service install" "$ST/log" && grep -q "tunnel: 6ff42ae2-" "$HOME/.cloudflared/aleph.yml" && grep -q "service: http://127.0.0.1:7878" "$HOME/.cloudflared/aleph.yml" && grep -q "<string>run</string>" "$HOME/Library/LaunchAgents/dev.aleph.cloudflared.plist" && printf "%s" "$o" | grep -q "Cloudflare Access" && [ "$(aleph settings get api.hosts </dev/null)" = aleph.example.com ] && aleph daemon status --json </dev/null | jq -e ".exposure.cloudflare.hostname == \"aleph.example.com\"" >/dev/null'
check "expose off cloudflare: our unit goes, the tunnel stays" sh -c 'export ALEPH_INIT=launchd; : > "$ST/log"; aleph daemon expose off cloudflare --yes </dev/null >/dev/null 2>&1 && [ ! -e "$HOME/Library/LaunchAgents/dev.aleph.cloudflared.plist" ] && grep -q "^launchctl bootout gui/[0-9]*/dev.aleph.cloudflared" "$ST/log" && ! grep -q "tunnel delete" "$ST/log" && [ -z "$(aleph settings get api.hosts </dev/null)" ]; r=$?; aleph settings unset api.http </dev/null >/dev/null; rm -rf "$HOME/.cloudflared" "$ST/cf_tunnels.json"; exit $r'
# --- deploying a daemon to a machine (b31 answers as Linux x86_64; fake cargo builds a stand-in)
echo "Linux x86_64" > "$ST/uname_b31"; echo b31 > "$ST/hostname_b31"
# a tiny checkout of "aleph" to plan from, with one file git doesn't track
mkdir -p "$ST/src/src" && printf '[package]\nname = "aleph"\nversion = "2.0.0"\n' > "$ST/src/Cargo.toml" && echo 'fn main() {}' > "$ST/src/src/main.rs" && (cd "$ST/src" && git init -q && git add -A && git -c user.name=smoke -c user.email=smoke@example.com commit -qm init) && touch "$ST/src/src/new_module.rs"
check "deploy --dry-run: the plan, nothing sent or built" sh -c ': > "$ST/log"; o=$(aleph daemon deploy b31 --build host --src "$ST/src" --dry-run </dev/null 2>&1) && printf "%s" "$o" | grep -q "nice -n 10 cargo build --release --locked" && printf "%s" "$o" | grep -q "git archive | ssh b31" && printf "%s" "$o" | grep -q "b31 becomes .local. there" && printf "%s" "$o" | grep -q "1 untracked file stays behind" && grep -q "^ssh .* b31 sh -s" "$ST/log" && ! grep -q "tar -xzf" "$ST/log" && ! grep -q "^cargo build" "$ST/log" && [ ! -e "$RHOME/.cache/aleph/src" ]'
check "deploy asks first (no tty, no --yes)"   sh -c ': > "$ST/log"; ! aleph daemon deploy b31 </dev/null >/dev/null 2>&1 && ! grep -q "tar -xzf" "$ST/log"'
check "deploy b31 --service --yes: source, build, binary, settings, service, status" sh -c 'aleph settings set notify.ntfy https://ntfy.sh/deploy-secret-zz </dev/null >/dev/null; : > "$ST/log"; o=$(aleph daemon deploy b31 --service --yes </dev/null 2>&1); r=$?; aleph settings unset notify.ntfy </dev/null >/dev/null; [ $r -eq 0 ] || { printf "%s" "$o"; exit 1; }; C="$RHOME/.config/aleph/aleph.toml"; grep -q "tar -xzf - -C" "$ST/log" && grep -q "^cargo build --release --locked (in .*rhome/.cache/aleph/src)" "$ST/log" && [ -x "$RHOME/.local/bin/aleph" ] && [ -f "$RHOME/.cache/aleph/src/Cargo.toml" ] && [ -s "$RHOME/.cache/aleph/src/.aleph-rev" ] && grep -q "machines = \[\"local\", \"gpu2\"\]" "$C" && grep -q "^machine = \"b31\"" "$C" && ! grep -q deploy-secret-zz "$C" && [ "$(aleph settings get hub.machine </dev/null)" = b31 ] && grep -q " daemon run$" "$RHOME/.config/systemd/user/aleph.service" && grep -q "^systemctl --user enable aleph.service" "$ST/log" && grep -q "^loginctl show-user" "$ST/log" && ! grep -q "enable-linger" "$ST/log" && printf "%s" "$o" | grep -q "ssh -t b31 sudo loginctl enable-linger" && jq -e ".b31.build == \"host\" and .b31.service and .b31.version == \"2.0.0\"" "$XDG_STATE_HOME/aleph/deploys.json" >/dev/null'
check "deploy again: the build cache and its settings stay" sh -c 'touch "$RHOME/.cache/aleph/src/target/keep-me"; C="$RHOME/.config/aleph/aleph.toml"; printf "\n# set on b31 by hand\n" >> "$C"; before=$(cksum < "$C"); o=$(aleph daemon deploy b31 --yes </dev/null 2>&1) && [ -e "$RHOME/.cache/aleph/src/target/keep-me" ] && [ -x "$RHOME/.cache/aleph/src/target/release/aleph" ] && printf "%s" "$o" | grep -q "it has its own: kept" && [ "$(cksum < "$C")" = "$before" ]'
check "deploy --build cross: missing zig is explained, nothing sent" sh -c ': > "$ST/log"; o=$(aleph daemon deploy b31 --build cross --yes </dev/null 2>&1); [ $? -ne 0 ] && printf "%s" "$o" | grep -q "zig" && printf "%s" "$o" | grep -q "cargo install --locked cargo-zigbuild" && printf "%s" "$o" | grep -q "installs nothing" && ! grep -q "cat > " "$ST/log" && ! grep -q "^cargo zigbuild" "$ST/log"'
check "deploy --build cross: zigbuild here, the binary over ssh" sh -c 'Z="$ST/zbin"; mkdir -p "$Z"; printf "#!/bin/sh\necho zig 0.13.0\n" > "$Z/zig"; printf "#!/bin/sh\necho cargo-zigbuild 0.19.0\n" > "$Z/cargo-zigbuild"; chmod +x "$Z/zig" "$Z/cargo-zigbuild"; export PATH="$Z:$PATH" CARGO_TARGET_DIR="$ST/target"; : > "$ST/log"; aleph daemon deploy b31 --build cross --config none --yes </dev/null >/dev/null 2>&1 && grep -q "^cargo zigbuild --release --locked --target x86_64-unknown-linux-musl" "$ST/log" && grep -q "cat > \"\$T\"" "$ST/log" && [ -x "$ST/target/x86_64-unknown-linux-musl/release/aleph" ] && echo "Linux aarch64" > "$ST/uname_b31" && aleph daemon deploy b31 --build cross --dry-run </dev/null 2>&1 | grep -q "aarch64-unknown-linux-musl"; r=$?; echo "Linux x86_64" > "$ST/uname_b31"; exit $r'
check "deploy: a dropped link mid-build says so" sh -c 'echo dropbuild > "$ST/mode_b31"; o=$(aleph daemon deploy b31 --config none --yes </dev/null 2>&1); r=$?; rm -f "$ST/mode_b31"; [ $r -ne 0 ] && printf "%s" "$o" | grep -q "dropped during the build" && printf "%s" "$o" | grep -q "run the same command again"'
check "deploy: a build that fails shows cargo's last lines" sh -c 'touch "$ST/cargo_fail"; o=$(aleph daemon deploy b31 --config none --yes </dev/null 2>&1); r=$?; rm -f "$ST/cargo_fail"; [ $r -ne 0 ] && printf "%s" "$o" | grep -q "error\[E0425\]" && printf "%s" "$o" | grep -q "cargo build failed on b31"'
check "update --json: the deployed daemon's version" sh -c 'aleph update --json </dev/null | jq -e ".daemons | length == 1 and .[0].host == \"b31\" and .[0].version == \"2.0.0\" and .[0].status == \"same\"" >/dev/null && aleph update --check </dev/null 2>/dev/null | grep -q "aleph daemons on other machines" && aleph daemon doctor --json </dev/null | jq -e "[.checks[] | select(.label == \"hub.machine\")][0].status == \"ok\"" >/dev/null'
check "doctor: a deployed daemon and hub.machine empty is two hubs" sh -c 'aleph settings unset hub.machine </dev/null >/dev/null; aleph daemon doctor --json </dev/null | jq -e "[.checks[] | select(.label == \"hub.machine\")][0] | .status == \"warn\" and (.fix[0] | startswith(\"aleph settings set hub.machine b31\"))" >/dev/null'
aleph settings unset hub.machine </dev/null >/dev/null 2>&1; rm -f "$ST/uname_b31" "$ST/hostname_b31"
check "daemon logs: the daemon's own lines only" sh -c 'ALEPH_LOG=debug aleph ls --json </dev/null >/dev/null; other=$(grep " proc: " "$XDG_STATE_HOME/aleph/aleph.log" | tail -n 1 | awk "{print \$3}"); aleph watch --interval 5 </dev/null >/dev/null 2>&1 & p=$!; sleep 3; kill $p; l=$(aleph daemon logs -n 5000 </dev/null 2>/dev/null); printf "%s" "$l" | grep -q "\[$p\] daemon: started" && [ -n "$other" ] && ! printf "%s" "$l" | grep -qF "$other"'
# setting a machine up: a bare one ($ST/bare_<host>: no herdr, no agents, no node),
# installs that fail ($ST/install_fail), the setup tab, the callback
check "host setup: asks first (no tty, no --yes)"  sh -c 'o=$(aleph host setup b31 </dev/null 2>&1); [ $? -ne 0 ] && printf "%s" "$o" | grep -q "asks before installing"'
check "host setup: a bare machine — herdr, Node.js LTS first, Claude Code ✓, Codex ✓, Cursor's download fails" sh -c ': > "$ST/bare_box3"; echo cursor.com > "$ST/install_fail"; : > "$ST/log"; o=$(aleph host setup box3 --yes --agents claude,codex,cursor </dev/null 2>&1); r=$?; rm -f "$ST/install_fail"; M="$XDG_STATE_HOME/aleph/refresh/box3.json"; B="${RHOME}_box3/.local/bin"; [ $r -ne 0 ] && grep -q "^herdr machine add box3" "$ST/log" && [ -x "$B/claude" ] && [ -x "$B/codex" ] && [ -L "$B/node" ] && printf "%s" "$o" | grep -q "Node.js v24.11.1 installed on box3" && printf "%s" "$o" | grep -q "sha256 matches nodejs.org" && ! grep -q "v25.1.0" "$ST/log" && printf "%s" "$o" | grep -q "Claude Code 2.1.200 installed on box3" && printf "%s" "$o" | grep -q "claude --version · 2.1.200" && printf "%s" "$o" | grep -q "codex --version · codex-cli 0.50.0" && printf "%s" "$o" | grep -q "a network error: box3 couldn" && printf "%s" "$o" | grep -q "2 installed · 1 failed" && printf "%s" "$o" | grep -q "left a note for Aleph" && grep -q "^claude current" "$ST/integ_box3" && grep -q "^codex current" "$ST/integ_box3" && jq -e ".what == \"setup\" and .herdr == \"0.9.5\" and .installed == [\"Claude Code\",\"Codex\"] and .failed == [\"Cursor CLI\"] and .report.node.version == \"v24.11.1\" and ([.report.results[].why] == [null,null,\"network\"]) and (.report.results[2].log | test(\"installs/box3-cursor-\"))" "$M" >/dev/null'
check "host setup: nodejs.org unreachable — Node.js and Codex say why; agents.node=off says how" sh -c ': > "$ST/bare_box6"; echo nodejs.org > "$ST/install_fail"; o=$(aleph host setup box6 --yes --no-herdr --agents codex </dev/null 2>&1); r=$?; rm -f "$ST/install_fail"; [ $r -ne 0 ] && printf "%s" "$o" | grep -q "couldn.t reach nodejs.org" && printf "%s" "$o" | grep -q "Codex installs with npm, and box6 has no Node.js" && printf "%s" "$o" | grep -q "Node.js couldn.t be installed" && [ ! -e "${RHOME}_box6/.local/bin/codex" ] && aleph settings set agents.node off </dev/null >/dev/null && o2=$(aleph host setup box6 --yes --no-herdr --agents codex </dev/null 2>&1); aleph settings unset agents.node </dev/null >/dev/null; printf "%s" "$o2" | grep -q "nvm install --lts" && ! printf "%s" "$o2" | grep -q "nodejs.org/dist"'
check "agents install: a Node.js download that fails its checksum installs nothing" sh -c ': > "$ST/bare_box7"; touch "$ST/node_badsum"; o=$(aleph agents install codex --host box7 --yes </dev/null 2>&1); r=$?; rm -f "$ST/node_badsum"; [ $r -ne 0 ] && printf "%s" "$o" | grep -q "didn.t match nodejs.org.s checksum" && [ ! -e "${RHOME}_box7/.local/bin/node" ] && [ ! -e "${RHOME}_box7/.local/share/aleph/node" ] && [ ! -e "${RHOME}_box7/.local/bin/codex" ]'
check "agents install: several, one after another; a failure never stops the rest" sh -c 'echo "@qwen-code/qwen-code" > "$ST/install_fail"; o=$(aleph agents install qwen gemini --host b31 --yes </dev/null 2>&1); r=$?; rm -f "$ST/install_fail"; [ $r -ne 0 ] && printf "%s" "$o" | grep -q "a network error: b31 couldn" && printf "%s" "$o" | grep -q "Gemini CLI 0.9.0 installed on b31" && printf "%s" "$o" | grep -q "1 installed · 1 failed" && [ -x "$RHOME/.npm-global/bin/gemini" ] && [ ! -e "$RHOME/.npm-global/bin/qwen" ] && ls "$XDG_STATE_HOME/aleph/installs/" | grep -q "^b31-qwen-"; r=$?; rm -rf "$RHOME/.npm-global"; exit $r'
check "host include: a bare machine's setup opens in a new tab, and tells Aleph when done" sh -c ': > "$ST/bare_box5"; touch "$ST/tab_run"; echo "--yes --agents claude" > "$ST/tab_append"; : > "$ST/log"; if script --version 2>/dev/null | grep -q util-linux; then o=$(script -qec "aleph host include box5" /dev/null </dev/null 2>&1); else o=$(script -q /dev/null aleph host include box5 </dev/null 2>&1); fi; r=0; printf "%s" "$o" | grep -q "has no herdr and no agents yet — its setup is open in a new" || r=1; grep -q "^TAB Aleph · set up box5 :: .* host setup box5 --tab" "$ST/log" || r=2; M="$XDG_STATE_HOME/aleph/refresh/box5.json"; i=0; until [ -f "$M" ] || [ $i -ge 150 ]; do sleep 0.2; i=$((i+1)); done; jq -e ".what == \"setup\" and .installed == [\"Claude Code\"] and .herdr == \"0.9.5\" and .probed" "$M" >/dev/null || r=3; rm -f "$ST/tab_run" "$ST/tab_append"; aleph host exclude box5 </dev/null >/dev/null 2>&1; [ $r -eq 0 ] || { echo "step $r"; printf "%s" "$o"; cat "$ST"/tab_*.out 2>/dev/null | tail -n 20; exit 1; }'
check "hosts.refresh: the daemon looks again, and host setup tells it" sh -c 'aleph watch --interval 5 </dev/null >/dev/null 2>&1 & p=$!; i=0; until aleph api daemon.ping </dev/null >/dev/null 2>&1 || [ $i -ge 40 ]; do sleep 0.25; i=$((i+1)); done; r=0; aleph api hosts.refresh "{\"host\":\"gpu2\",\"what\":\"setup\",\"herdr\":\"0.9.5\"}" </dev/null | jq -e ".by == \"daemon\" and .in_fleet" >/dev/null || r=1; jq -e ".what == \"setup\" and .herdr == \"0.9.5\"" "$XDG_STATE_HOME/aleph/refresh/gpu2.json" >/dev/null || r=2; sleep 1; grep -q "gpu2 changed (set up)" "$XDG_STATE_HOME/aleph/aleph.log" || r=3; aleph api hosts.refresh "{\"host\":\"nosuch\"}" </dev/null >/dev/null 2>&1 && r=4; o=$(aleph host setup gpu2 --yes --no-herdr --agents codex </dev/null 2>&1); printf "%s" "$o" | grep -q "Codex 0.40.1 is already installed on gpu2" || r=5; printf "%s" "$o" | grep -q "told the daemon" || r=6; kill $p; [ $r -eq 0 ] || { echo "step $r"; printf "%s" "$o"; exit 1; }'
rm -f "$ST"/bare_box*
# backup: one file, never a secret; a restore asks, keeps this computer's secrets, and saves what it replaced
check "backup: settings and notes in one file, the ntfy secret left out" sh -c 'aleph settings set notify.ntfy https://ntfy.sh/smoke-secret </dev/null >/dev/null 2>&1 && aleph settings set ui.splash classic </dev/null >/dev/null 2>&1 && aleph note b31:claude_ignite "backup me" </dev/null >/dev/null 2>&1; F="$XDG_DATA_HOME/aleph/smoke-backup.json"; aleph backup "$F" </dev/null >/dev/null 2>&1 && jq -e ".aleph_backup == 1 and (.files | has(\"config/aleph.toml\")) and (.left_out[\"config/aleph.toml\"] == [\"notify.ntfy\"])" "$F" >/dev/null && ! grep -q smoke-secret "$F"'
check "backup restore: shows the change, asks, keeps our secret, saves what it replaced" sh -c 'F="$XDG_DATA_HOME/aleph/smoke-backup.json"; aleph settings set ui.splash off </dev/null >/dev/null 2>&1; aleph settings set notify.ntfy https://ntfy.sh/ours </dev/null >/dev/null 2>&1; o=$(aleph backup restore "$F" </dev/null 2>&1); [ $? -ne 0 ] && [ "$(aleph settings get ui.splash </dev/null)" = off ] && o=$(aleph backup restore "$F" --yes </dev/null 2>&1) && printf "%s" "$o" | grep -q "ui.splash: off → classic" && [ "$(aleph settings get notify.ntfy </dev/null)" = https://ntfy.sh/ours ] && ls "$XDG_DATA_HOME/aleph/backups/" | grep -q "^before-restore-"; r=$?; aleph settings unset notify.ntfy </dev/null >/dev/null 2>&1; aleph settings unset ui.splash </dev/null >/dev/null 2>&1; exit $r'
check "backup restore: a file aimed outside its places is refused" sh -c 'F="$XDG_DATA_HOME/aleph/evil.json"; printf "%s" "{\"aleph_backup\":1,\"files\":{\"config/../../evil.toml\":\"x = 1\",\"state/daemon.sock\":\"x\"}}" > "$F"; o=$(aleph backup restore "$F" --yes </dev/null 2>&1); printf "%s" "$o" | grep -q "not restored" && [ ! -e "$XDG_DATA_HOME/evil.toml" ] && [ ! -e "$HOME/evil.toml" ]'
# aleph:// links: opening ones open a tab; acting ones ask (the fake osascript answers with $ST/dialog)
check "url: approve asks first, showing its screen; Approve sends the yes option" sh -c ': > "$ST/log"; rm -f "$ST/dialog.log"; echo Approve > "$ST/dialog"; aleph url "aleph://approve?session=b31%3Atemper" </dev/null >/dev/null 2>&1; r=$?; rm -f "$ST/dialog"; [ $r -eq 0 ] && grep -q "agent send-keys w1:p2 1" "$ST/log" && grep -q "Answer yes to b31:temper" "$ST/dialog.log" && grep -q "Its screen now" "$ST/dialog.log"'
check "url: cancelled, nothing is sent" sh -c ': > "$ST/log"; rm -f "$ST/dialog"; ! aleph url "aleph://send?session=b31:temper&text=rm+-rf+%2F" </dev/null >/dev/null 2>&1 && ! grep -q "send-keys\|send-text\|agent send" "$ST/log"'
check "url: open and focus open a tab, without asking" sh -c ': > "$ST/log"; rm -f "$ST/dialog.log"; aleph url "aleph://focus?session=b31:ignite" </dev/null >/dev/null 2>&1 && aleph url "aleph://open?view=monitor" </dev/null >/dev/null 2>&1 && grep -q "^TAB .*focus.*b31:ignite" "$ST/log" && grep -q "^TAB .* ui.*monitor" "$ST/log" && [ ! -e "$ST/dialog.log" ]'
check "url: unknown links and bad parameters are refused" sh -c '! aleph url "aleph://rm?session=x" </dev/null >/dev/null 2>&1 && ! aleph url "aleph://new?dir=relative" </dev/null >/dev/null 2>&1'
# settings profiles: layered over yours, off brings yours back, the daemon notices
check "profile: work over yours, off brings yours back, your file untouched" sh -c 'aleph settings set ui.splash classic </dev/null >/dev/null 2>&1; before=$(cat "$HOME/.config/aleph/aleph.toml"); aleph profile use work </dev/null >/dev/null 2>&1 && [ "$(aleph settings get ui.splash </dev/null)" = off ] && aleph profile show work --json </dev/null | jq -e ".settings[] | select(.key == \"ui.splash\") | .yours == \"classic\"" >/dev/null && [ "$(cat "$HOME/.config/aleph/aleph.toml")" = "$before" ] && aleph profile off </dev/null >/dev/null 2>&1 && [ "$(aleph settings get ui.splash </dev/null)" = classic ]; r=$?; aleph profile off </dev/null >/dev/null 2>&1; aleph settings unset ui.splash </dev/null >/dev/null 2>&1; exit $r'
check "profile: save, set, delete; bad names and unknown keys refused" sh -c 'aleph settings set refresh 3 </dev/null >/dev/null 2>&1; aleph profile save mine refresh </dev/null >/dev/null 2>&1 && aleph profile set mine ui.splash classic </dev/null >/dev/null 2>&1 && aleph profile show mine --json </dev/null | jq -e "[.settings[].key] | (index(\"refresh\") != null) and (index(\"ui.splash\") != null)" >/dev/null && ! aleph profile use ../x </dev/null >/dev/null 2>&1 && ! aleph profile set mine nosuch 1 </dev/null >/dev/null 2>&1 && ! aleph profile rm mine </dev/null >/dev/null 2>&1 && aleph profile rm mine --yes </dev/null >/dev/null 2>&1 && [ ! -e "$HOME/.config/aleph/profiles/mine.toml" ]; r=$?; aleph settings unset refresh </dev/null >/dev/null 2>&1; exit $r'
check "profile: the daemon reads the settings again when one is switched" sh -c 'L="$XDG_STATE_HOME/aleph/aleph.log"; aleph settings set hub.machine elsewhere </dev/null >/dev/null 2>&1; aleph watch --interval 5 </dev/null >/dev/null 2>&1 & p=$!; i=0; until [ "$(aleph api daemon.ping </dev/null 2>/dev/null | jq -r .pid)" = "$p" ] || [ $i -ge 60 ]; do sleep 0.25; i=$((i+1)); done; sleep 3; u=$(aleph profile use travel </dev/null 2>&1); i=0; until grep -q "\[$p\] daemon: the settings changed: read them again" "$L" || [ $i -ge 120 ]; do sleep 0.25; i=$((i+1)); done; grep -q "\[$p\] daemon: the settings changed: read them again" "$L"; r=$?; [ $r -eq 0 ] || { echo "daemon $p, ping: $(aleph api daemon.ping </dev/null 2>&1)"; echo "$u"; tail -n 6 "$L"; }; kill $p; aleph profile off </dev/null >/dev/null 2>&1; aleph settings unset hub.machine </dev/null >/dev/null 2>&1; exit $r'
# the prompt library: @name filled in for the session, missing variables refused
check "prompt: @name is filled in for the session, --var gives the rest" sh -c 'set -- $(fake-live-session); [ -n "$1" ] || exit 9; aleph prompt add fixit "Fix {ticket} in {folder}" </dev/null >/dev/null 2>&1; : > "$ST/log"; aleph send "$1:$2" @fixit --var ticket=VD-7 </dev/null >/dev/null 2>&1; grep -q "agent prompt $3 Fix VD-7 in $(basename "$4")" "$ST/log" && ! aleph send "$1:$2" @fixit </dev/null >/dev/null 2>&1 && aleph prompt ls --json </dev/null | jq -e "any(.[]; .name == \"fixit\" and .vars == [\"ticket\",\"folder\"])" >/dev/null; r=$?; aleph prompt rm fixit </dev/null >/dev/null 2>&1; exit $r'
# hand-offs: Aleph's note, or the agent's (none here: Aleph's instead), a new session with it
check "handoff: Aleph's note starts another agent in the same folder; no agent note falls back" sh -c 'set -- $(fake-live-session); [ -n "$1" ] || exit 9; : > "$ST/log"; o1=$(aleph handoff "$1:$2" --to codex --summary aleph --json </dev/null 2>&1); o2=$(aleph handoff "$1:$2" --to opencode --json </dev/null 2>&1); r=0; printf "%s" "$o1" | jq -e ".to == \"codex\" and .note_by == \"aleph\"" >/dev/null || r=1; grep -q "agent start .* --kind codex .*taking over a task from another coding agent" "$ST/log" || r=2; grep -q "tab create .*--cwd .*$(basename "$4")" "$ST/log" || r=3; printf "%s" "$o2" | jq -e ".note_by == \"aleph\" and (.fell_back | test(\"didn.t write its note|usage limit\"))" >/dev/null || r=4; [ "$(grep -c "took over from $2 " "$XDG_STATE_HOME/aleph/events.jsonl")" -ge 2 ] || r=5; [ $r -eq 0 ] || { echo "step $r on $*"; echo "$o1"; echo "$o2"; grep -E "tab create|agent start" "$ST/log" | tail -n 4 | cut -c1-160; }; exit $r'
# races: one prompt, each agent in a worktree of its own, recorded
check "race: claude vs codex, each in its own worktree, the same prompt, recorded" sh -c 'R="$RHOME/race-repo"; mkdir -p "$R" && (cd "$R" && git init -q && git -c user.email=t@t -c user.name=t commit -q --allow-empty -m base) && : > "$ST/log" && aleph race "make the LUT fit faster" --agents claude,codex --host b31 --dir "$R" </dev/null >/dev/null 2>&1 && grep -q "worktree create .*--branch race/.*-claude" "$ST/log" && grep -q "worktree create .*--branch race/.*-codex" "$ST/log" && [ "$(grep -c "agent start .*-- make the LUT fit faster$" "$ST/log")" -eq 2 ] && aleph race ls --json </dev/null | jq -e ".[0].racers | length == 2" >/dev/null && ! aleph race "x" --agents claude --host b31 --dir "$R" </dev/null >/dev/null 2>&1'
# open in editor: another machine's folder over Remote-SSH (the fake editor logs it)
check "edit: a session's folder in the editor, over Remote-SSH for another machine" sh -c 'set -- $(fake-live-session); [ -n "$1" ] || exit 9; : > "$ST/log"; aleph edit "$1:$2" </dev/null >/dev/null 2>&1 || exit 1; i=0; until grep -q "^EDITOR ssh-remote+$1 $4$" "$ST/log" || [ $i -ge 20 ]; do sleep 0.1; i=$((i+1)); done; grep -q "^EDITOR ssh-remote+$1 $4$" "$ST/log"'
# closing after close.grace: no hub, the CLI waits it out (an undo from
# elsewhere keeps it); with the daemon, it's handed over and carried out there
check "close: no hub, the grace is waited here; --undo from another shell keeps it" sh -c 'set -- $(fake-live-session); [ -n "$1" ] || exit 9; A="$ST/agents_$1.json"; cp "$A" "$A.cl"; aleph settings set close.grace 3s </dev/null >/dev/null; : > "$ST/log"; aleph close "$1:$2" --yes </dev/null >"$ST/cl.out" 2>&1 & p=$!; sleep 1; r=0; aleph close --pending </dev/null | grep -q "	$3	" || r=1; aleph close --undo "$1:$2" </dev/null >/dev/null || r=2; wait $p; [ $? -eq 1 ] || r=3; grep -q "kept" "$ST/cl.out" || r=4; grep -q "pane close $3" "$ST/log" && r=5; [ -e "$XDG_STATE_HOME/aleph/closing.json" ] && r=6; aleph close "$1:$2" --yes --now --json </dev/null | jq -e ".closed" >/dev/null || r=7; grep -q "pane close $3" "$ST/log" || r=8; cp "$A.cl" "$A"; aleph settings unset close.grace </dev/null >/dev/null; [ $r -eq 0 ] || { echo "step $r on $*"; cat "$ST/cl.out"; exit 1; }'
check "close: the daemon carries it out after the grace; the API says pending, its undo keeps it" sh -c 'set -- $(fake-live-session); [ -n "$1" ] || exit 9; A="$ST/agents_$1.json"; cp "$A" "$A.cl"; aleph settings set close.grace 2s </dev/null >/dev/null; aleph watch --interval 5 </dev/null >/dev/null 2>&1 & p=$!; i=0; until aleph api daemon.ping </dev/null >/dev/null 2>&1 || [ $i -ge 40 ]; do sleep 0.25; i=$((i+1)); done; sleep 1; : > "$ST/log"; r=0; aleph api session.close "{\"session\":\"$1:$2\"}" </dev/null | jq -e ".pending and .deadline > 0" >/dev/null || r=1; aleph api session.close.undo "{\"session\":\"$1:$2\"}" </dev/null | jq -e ".names | length == 1" >/dev/null || r=2; o=$(aleph close "$1:$2" --yes </dev/null 2>&1); printf "%s" "$o" | grep -q "close --undo" || r=3; grep -q "pane close $3" "$ST/log" && r=4; sleep 3.5; grep -q "pane close $3" "$ST/log" || r=5; grep -q "closing: closed .* (asked by cli)" "$XDG_STATE_HOME/aleph/aleph.log" || r=6; kill $p; cp "$A.cl" "$A"; aleph settings unset close.grace </dev/null >/dev/null; [ $r -eq 0 ] || { echo "step $r on $*"; echo "$o"; exit 1; }'
# the session journal: a Markdown file a day (prompts kept only while included,
# secrets masked; git in each folder; journal.include, journal.dir)
check "journal: a prompt sent through Aleph lands in today's file, its secret masked" sh -c 'set -- $(fake-live-session); [ -n "$1" ] || exit 9; aleph send "$1:$2" "Fix the flaky test, key sk-ant-api03-AbCdEf1234567890abcdefXYZ" </dev/null >/dev/null 2>&1 || exit 1; aleph journal --write </dev/null >/dev/null 2>&1 || exit 2; F="$XDG_DATA_HOME/aleph/journal/$(date +%F).md"; grep -q "^## $2 · $1" "$F" && grep -q "Fix the flaky test, key …" "$F" && ! grep -q "sk-ant-api03" "$F" "$XDG_STATE_HOME/aleph/sent.jsonl" && grep -q "^\*\*Files\*\*" "$F" && grep -q "typed straight into an agent in herdr" "$F"'
check "journal --json: each session with its prompts, and what's included" sh -c 'set -- $(fake-live-session); [ -n "$1" ] || exit 9; aleph journal --json </dev/null | jq -e --arg h "$1" --arg n "$2" "(.include | index(\"prompts\") != null) and any(.sessions[]; .host == \$h and .name == \$n and (.prompts | length) >= 1)" >/dev/null'
check "journal.include: prompts left out are never kept or shown; off means no journal" sh -c 'set -- $(fake-live-session); [ -n "$1" ] || exit 9; aleph settings set journal.include finals,files,cost </dev/null >/dev/null; aleph send "$1:$2" "a plan nobody should keep" </dev/null >/dev/null 2>&1; aleph journal --write </dev/null >/dev/null 2>&1; o=$(aleph journal </dev/null 2>/dev/null); aleph settings set journal.include off </dev/null >/dev/null; aleph journal </dev/null >/dev/null 2>&1; off=$?; aleph settings unset journal.include </dev/null >/dev/null; [ $off -ne 0 ] && ! grep -q "a plan nobody should keep" "$XDG_STATE_HOME/aleph/sent.jsonl" && printf "%s" "$o" | grep -q "^# Journal" && ! printf "%s" "$o" | grep -q "Prompts"'
check "journal: a day with nothing says so; journal.dir moves the files" sh -c 'aleph journal 2020-01-01 </dev/null 2>/dev/null | grep -q "Nothing ran through Aleph" || exit 1; aleph settings set journal.dir "$ST/jr" </dev/null >/dev/null; aleph journal --write </dev/null >/dev/null 2>&1; r=$?; d=$(aleph journal path </dev/null); aleph settings unset journal.dir </dev/null >/dev/null; [ $r -eq 0 ] && [ "$d" = "$ST/jr" ] && [ -f "$ST/jr/$(date +%F).md" ]'
echo
echo "$pass passed, $fail failed"
[ "$fail" -eq 0 ]
